/* --- offer / lease arvutusi ------------------------------------------------
   Hind pinna kohta pakkumises, kolm taset:
   1) hinnakirja hind (sp.hind)
   2) erihind (o.hinnad[spaceId] — üks number)
   3) hinnagraafik (o.graafik[spaceId] — astmeline üür: [{kuniKuu, hind}, …, {kuniKuu:null, hind}])
   Põhihind = viimase astme hind; sellest arvestatakse tagatis ja indekseerimine. */
function offerPriceRows(offer, sp) {
  const g = offer.graafik && offer.graafik[sp.id];
  if (g && g.length) return g;
  const h = (offer.hinnad && offer.hinnad[sp.id] != null) ? offer.hinnad[sp.id] : sp.hind;
  return [{ kuniKuu: null, hind: h }];
}
function offerPrice(offer, sp) { const r = offerPriceRows(offer, sp); return r[r.length - 1].hind; }
function pricePeriods(offer, sp) {
  let from = 1;
  return offerPriceRows(offer, sp).map(p => { const seg = { from, to: p.kuniKuu, hind: p.hind, rent: sp.yyripind * p.hind }; from = (p.kuniKuu || 0) + 1; return seg; });
}
function perLabel(from, to) { return to == null ? `alates ${from}. kuust` : `${from}.–${to}. kuu`; }
function offerTotals(offer) {
  const spaces = offer.spaceIds.map(DB.spaceById);
  const rows = spaces.map(sp => { const periods = pricePeriods(offer, sp); const base = periods[periods.length - 1];
    return { sp, periods, hind: base.hind, rent: base.rent, astmeline: periods.length > 1 }; });
  const rentSum = rows.reduce((s, r) => s + r.rent, 0); // põhihindade järgi
  const astmeline = rows.some(r => r.astmeline);
  let segments = null, avgM2 = 0, avgSum = 0;
  if (astmeline) {
    /* ühisperioodid: kõigi pindade astmepiirid koos, summa segmendi kaupa */
    const bounds = [...new Set(rows.flatMap(r => r.periods.map(p => p.to).filter(x => x != null)))].sort((a, b) => a - b);
    let from = 1;
    segments = [...bounds, null].map(end => {
      const sum = rows.reduce((s, r) => s + r.periods.find(x => x.to == null || x.to >= from).rent, 0);
      const seg = { from, to: end, sum }; from = (end || 0) + 1; return seg;
    });
    const kuud = offer.pikkusKuud || 0;
    let tot = 0;
    segments.forEach(sg => { const b = Math.min(sg.to || kuud, kuud); if (b >= sg.from) tot += sg.sum * (b - sg.from + 1); });
    avgSum = kuud ? tot / kuud : 0;
    const m2tot = spaces.reduce((s, sp) => s + sp.yyripind, 0);
    avgM2 = m2tot ? avgSum / m2tot : 0;
  }
  const kkWin = spaces.reduce((s, sp) => s + kkWinter(sp), 0);
  const kkSum = spaces.reduce((s, sp) => s + kkSummer(sp), 0);
  return { spaces, rows, rentSum, astmeline, segments, avgM2, avgSum, kuud: offer.pikkusKuud,
           kkWin, kkSum, parking: spaces.reduce((s, sp) => s + offerParking(offer, sp), 0),
           elekter: spaces.reduce((s, sp) => s + offerElekter(offer, sp), 0) };   /* v788: pakkumise elektrivõimsus kokku */
}
/* pakkumise kontaktisik: pakkumisele salvestatu või vaikimisi kliendi andmed */
function offerContact(o, cl) { return o.kontakt || { nimi: cl.kontakt, epost: cl.epost, tel: cl.tel || "" }; }

/* --- PARKIMISKOHAD JA LISAD ON PAKKUMUSE OMAD (v462) -------------------------
   Üks allikas: o.parkimine[pinnaId] (vaikimisi pinna kohad) ja o.lisad (vaikimisi
   pinnaplaanid + asendiplaan). Dokument, kokkuvõte, diff ja leping loevad siit —
   arvu muudetakse ÜHES kohas (Üüripinnad) ja see uueneb kõikjal. */
const offerParking = (o, sp) => (o.parkimine && o.parkimine[sp.id] != null) ? o.parkimine[sp.id] : (sp.parkimine || 0);
/* v788 (kasutaja 30.09): elektrivõimsus pinna kaupa (A) — vaikimisi pinna oma, pakkumises muudetav (üürnik võib soovida suuremat);
   lisaomadused = vaba nimekiri {silt, v} (nt põranda kandevõime) — dokumendis ja versioonide võrdluses */
const offerElekter = (o, sp) => (o.elekter && o.elekter[sp.id] != null) ? o.elekter[sp.id] : (sp.elekter || 0);
const offerOmadused = (o) => (o.omadused || []).filter(x => x && String(x.silt || "").trim() && String(x.v || "").trim());
const OMADUS_SOOVITUS = ["Põranda kandevõime", "Laekõrgus", "Tõsteuks", "Laadimisramp", "Ventilatsioon", "Küte", "Jahutus", "Valve ja ligipääs", "Internetiühendus"];
function offerLisadDefault(o) {
  const sps = (o.spaceIds || []).map(DB.spaceById).filter(Boolean);
  if (!sps.length) return [];
  return sps.map(sp => ({ id: "pp-" + sp.id, nr: 1, nimi: `Pinnaplaan (${sp.nimi})`, fail: sp.plaanFail || objektOf(sp).failid.pinnaplaan || null, spaceId: sp.id }))
    .concat([parkOn(objektOf(sps[0]).id) ? { id: "ap", nr: 2, nimi: "Parkimiskohad", fail: "park:" }
      : { id: "ap", nr: 2, nimi: "Asendiplaan + parkimisskeem", fail: objektOf(sps[0]).failid.parkimine || null }]);
}
const offerLisad = (o) => (o.lisad || offerLisadDefault(o)).map(x => x.spaceId ? { ...x, fail: plaanFix(x.fail, x.spaceId) }
    : x.id === "ap" ? (f => ({ ...x, fail: f, nimi: isParkFail(f) ? "Parkimiskohad" : x.nimi }))(parkFix(x.fail, parkObjOfSpace(DB.spaceById((o.spaceIds || [])[0]))))
    : x).sort((a, b) => a.nr - b.nr);
/* hetktõmmis hoiab üles laaditud faili asemel ainult viidet — fail tuleb elavalt pakkumiselt */
function offerLisaFail(o, x) {
  if (x.fail) return x.fail;
  const live = DB.offerById(o.id), m = live && (live.lisad || []).find(y => y.id === x.id);
  return (m && m.fail) || null;
}
window.openOfferLisa = (oid, lid) => {
  const o = DB.offerById(oid); if (!o) return;
  const x = offerLisad(isClient() ? offerSentView(o) : o).find(y => y.id === lid); if (!x) return;
  if (isParkFail(x.fail)) { openParkLisa("o", o.id); return; }   /* v551: genereeritud parkimisplaan */
  openPdf(offerLisaFail(o, x), `Lisa ${x.nr} · ${x.nimi}`);
};
/* vabatekstis („koos 4 parkimiskohaga") järgib arv sama allikat — asendatakse ainult vana koguarv */
function syncParkingText(txt, vana, uus) {
  if (!txt || vana === uus) return txt;
  return txt.replace(/(\d+)(\s+)(parkimiskoh[a-zõäöü]*)/gi, (m, n, ws, w) => {
    if (+n !== vana) return m;
    const word = /^parkimiskohta$/i.test(w) && uus === 1 ? "parkimiskoht" : /^parkimiskoht$/i.test(w) && uus !== 1 ? "parkimiskohta" : w;
    return uus + ws + word;
  });
}

/* ===================== PARKIMISKOHAD (v551) =====================================
   Parkimiskoht on ERALDI ese, seotud hoonega (objektiga) — mitte pinnaga. Kohad tulevad hoone
   parkimisplaanist (PARK_SVGS, data.js); hõive TULETATAKSE dokumentidest:
     leping (l.tehing.parkKohad) › imporditud leping („Parkimine … nr 65 ja 101") › pakkumine (o.parkKohad);
   registris saab koha märkida kasutusest välja (PARK_MUUD). Pakkumus/leping määrab kohad plaanilt
   (parkPick) → Lisa 2 genereeritakse samast plaanist (fail = "park:"). Kehtival lepingul saab kohti
   VAHETADA (sama arv) — muutus läheb P 2.2 ajalukku ja l.parkAjalugu-sse. */
const parkSvg = (objId) => (PARK_SVGS && PARK_SVGS[objId]) || null;
const PARK_INFO = {};
/* kohad + uksed plaanilt (ilma DOM-ita): { kohad: [{nr, lig, cx, cy}], uksed: {pinnaNr: [{x, y}]} } */
function parkInfo(objId) {
  if (PARK_INFO[objId]) return PARK_INFO[objId];
  const s = parkSvg(objId); if (!s) return null;
  const kohad = [], uksed = {};
  const reK = /<g id="space-\d+" class="parking-space( accessible)?" data-number="(\d+)"[\s\S]*?points="([^"]+)"/g; let m;
  while ((m = reK.exec(s))) {
    const pts = m[3].trim().split(/\s+/).map(p => p.split(",").map(Number));
    kohad.push({ nr: +m[2], lig: !!m[1], cx: pts.reduce((a, p) => a + p[0], 0) / pts.length, cy: pts.reduce((a, p) => a + p[1], 0) / pts.length });
  }
  const reU = /data-unit="(\d+)"[^>]*>[\s\S]*?translate\(([\d.]+) ([\d.]+)\)/g;
  while ((m = reU.exec(s))) (uksed[m[1]] = uksed[m[1]] || []).push({ x: +m[2], y: +m[3] });
  kohad.sort((a, b) => a.nr - b.nr);
  return PARK_INFO[objId] = { kohad, uksed };
}
const parkObjOfSpace = (sp) => sp ? objektOf(sp).id : null;
/* v660 (kasutaja: parkimise haldus): PARKIMISREGISTER = hoone kohtade loend { nr, tsoon, tyyp, uld }. Register on alus,
   plaan (PARK_SVGS) on valikuline kiht: plaaniga hoonel tuleb vaikeregister plaanilt + PARK_ERI; salvestatud PARK_REG[objId]
   kirjutab üle (tüüp, tsoon, üldkasutatav). Plaanita hoone kohad luuakse vahemikuga või tabelist (#/parkimine/<objId>) ja
   valitakse kiipidega. Kõik (hõive, pakkumine, leping, Lisa 2, P 2.2) küsib parkOn/parkReg, mitte plaani. */
/* v663 (kasutaja): reserv on LIPP (k.uld — endine „üldkasutatav"), mitte tüüp; reservi ja elektriauto kohti saab pakkumuses/lepingus
   vabalt valida (automaatvalik „lähimad" neid ei võta); elektriauto kohad on plaanil/kiipidel eraldi värviga */
const PARK_TYYBID = [["tavaline", "Tavaline"], ["elekter", "Elektriauto"], ["inva", "Ligipääsetav"]];
const parkTyypNimi = (t) => (PARK_TYYBID.find(x => x[0] === t) || [, "Tavaline"])[1];
function parkReg(objId) {
  if (PARK_REG[objId]) { PARK_REG[objId].forEach(k => { if (k.tyyp === "reserv") { k.tyyp = "tavaline"; k.uld = true; } }); return PARK_REG[objId]; }
  const info = parkInfo(objId); if (!info) return null;
  const eri = (PARK_ERI || {})[objId] || {}, on = (k, nr) => (eri[k] || []).includes(nr);
  return info.kohad.map(k => ({ nr: k.nr, tsoon: "", tyyp: on("elekter", k.nr) ? "elekter" : on("inva", k.nr) || k.lig ? "inva" : "tavaline",
    uld: on("inva", k.nr) || on("reserv", k.nr) }));
}
const parkOn = (objId) => !!objId && (parkReg(objId) || []).length > 0;
const parkPlaaniga = (objId) => !!parkSvg(objId);
const PARK_VANAD = ["lisad/T6B_parkimisskeem.pdf"];
const isParkFail = (f) => f === "park:";
/* vana staatiline parkimisskeem (Lisa 2) → genereeritud plaan, kui hoonel on parkimisplaan */
function parkFix(fail, objId) {
  if (!parkOn(objId)) return fail;
  const ob = OBJEKTID.find(o => o.id === objId);
  return (!fail || isParkFail(fail) || PARK_VANAD.includes(fail) || (ob && ob.failid && fail === ob.failid.parkimine) || /^—/.test(fail)) ? "park:" : fail;
}
const parkNrTxt = (a) => (a || []).slice().sort((x, y) => x - y).join(", ");
/* v586: pinna vaikekohad (maja jaotus, t6b-parkimine.xlsx) — n esimest, kui pakkumise arv on väiksem */
const pinnaKohad = (sp, n) => (sp && sp.parkKohad ? sp.parkKohad.slice(0, n == null ? undefined : n) : []);
/* pakkumise kohad: käsitsi määratud (o.parkKohad massiiv) VÕI pindade vaikekohad */
function offerParkKohad(o) {
  if (Array.isArray(o.parkKohad)) return o.parkKohad;
  return (o.spaceIds || []).map(DB.spaceById).filter(Boolean).flatMap(sp => pinnaKohad(sp, offerParking(o, sp)));
}
const offerParkVaikimisi = (o) => !Array.isArray(o.parkKohad);
/* hõive: nr → { olek, kes, ref, href, rank } — madalam rank võidab (väljas < leping < import < pakkumine) */
function parkHoive(objId, valja) {
  const map = new Map();
  const put = (nr, v) => { const c = map.get(nr); if (!c || v.rank < c.rank) map.set(nr, v); };
  LEASES.forEach(l => {
    const sp = DB.spaceById(l.spaceId); if (!sp || parkObjOfSpace(sp) !== objId || lepArh(l)) return;
    if (valja && valja.kind === "l" && valja.id === l.id) return;
    const cl = DB.clientById(l.clientId), s = lepSigned(l);
    lepParkKohad(l).forEach(nr => put(nr, { rank: s ? 1 : 2, olek: "Üüritud", kes: cl ? cl.nimi : "—", ref: l.id, href: "#/leping/" + l.id, allkirjastamata: !s }));   /* v663: üks olek (kasutaja) */
  });
  IMPORDITUD.forEach(x => {
    if (x.liik !== "Üürileping") return;
    const sp = (x.pindIds || []).map(DB.spaceById).find(Boolean); if (!sp || parkObjOfSpace(sp) !== objId) return;   /* v805 audit 1: ID järgi */
    const par = (x.parameetrid || []).find(p => p[0] === "Parkimine");
    const nrs = par ? (String(par[1]).match(/nr\s+([^·]+)/i) || [, ""])[1].match(/\d+/g) || [] : [];
    nrs.forEach(n => put(+n, { rank: 1, olek: "Üüritud", kes: x.pool, ref: x.id, href: "#/imp/" + x.id }));
  });
  OFFERS.forEach(o => {
    if (OFFER_LOPP.includes(o.staatus)) return;
    if (valja && valja.kind === "o" && valja.id === o.id) return;
    const sp = DB.spaceById((o.spaceIds || [])[0]); if (!sp || parkObjOfSpace(sp) !== objId) return;
    const cl = DB.clientById(o.clientId);
    offerParkKohad(o).forEach(nr => put(nr, { rank: 3, olek: "Pakkumises", kes: cl ? cl.nimi : "—", ref: o.id, href: "#/pakkumus/" + o.id }));
  });
  /* v586: maja vaikejaotus — hõivatud pinna kohad on hõivatud (ka kui lepingut süsteemis pole); vaba pinna kohad on
     pinnale määratud, aga ümber määratavad (pehme); oma dokumendi pinna kohad on alati vabad */
  const omad = valja ? (valja.kind === "o" ? ((DB.offerById(valja.id) || {}).spaceIds || []) : lepPindIds(DB.leaseById(valja.id) || {})) : [];
  SPACES.filter(sp => pindYksus(sp) && parkObjOfSpace(sp) === objId && (sp.parkKohad || []).length && !omad.includes(sp.id)).forEach(sp => {
    if (LEASES.some(l => lepOnPind(l, sp.id) && !lepArh(l))) return;
    if (OFFERS.some(o => (o.spaceIds || []).includes(sp.id) && !OFFER_LOPP.includes(o.staatus))) return;
    const hoivatud = ["Üüritud", "Lepingus"].includes(sp.staatus);
    sp.parkKohad.forEach(nr => put(nr, hoivatud
      ? { rank: 4, olek: "Üüritud", kes: `${sp.nimi}${sp.tenant ? " · " + sp.tenant : ""}`, ref: sp.nimi, href: "#/objekt/" + objId }
      : { rank: 6, olek: "Pinnale määratud", kes: `${sp.nimi} (vaba pind)`, ref: sp.nimi, href: "#/objekt/" + objId, pehme: true }));
  });
  (parkReg(objId) || []).filter(k => k.uld || k.tyyp === "elekter").forEach(k => put(k.nr, k.tyyp === "elekter" && !k.uld
    ? { rank: 5, olek: "Elektriauto", kes: "laadimisega koht · valitav", vaba: true }
    : { rank: 5, olek: "Reserv", kes: `${k.tyyp === "elekter" ? "elektriauto · " : k.tyyp === "inva" ? "ligipääsetav · " : ""}valitav vajadusel`, vaba: true, uld: true }));
  Object.keys(PARK_MUUD).forEach(k => {
    const [oid, nr] = k.split(":"), v = PARK_MUUD[k];
    if (oid === objId && v && v.blokk) put(+nr, { rank: 0, olek: "Kasutusest väljas", kes: v.markus || "", blokk: true });
  });
  return map;
}
const PARK_TOON = { "Üüritud": "pk-ren", "Lepingus": "pk-ren", "Pakkumises": "pk-off", "Kasutusest väljas": "pk-out", "Reserv": "pk-com", "Elektriauto": "pk-ev", "Pinnale määratud": "pk-pind" };
let PARK_UID = 0;
/* plaan + genereeritud värvireeglid (valitud kollane, hõivatud hall, pakkumises hele, väljas triibuline);
   pindNr = selle pinna uks/silt esile */
function parkPlaanHTML(objId, o = {}) {
  const s = parkSvg(objId); if (!s) return parkKiibidHTML(objId, o);   /* v660: plaanita hoone → kohad kiipidena */
  const cls = "pkh" + (++PARK_UID), sel = o.valitud || [], hoive = o.hoive || new Map();
  const r = [];
  hoive.forEach((v, nr) => { if (!sel.includes(nr)) r.push(`.${cls} g.parking-space[data-number="${nr}"]{--pk:var(--${PARK_TOON[v.olek] || "pk-ren"})}`); });
  sel.forEach(nr => r.push(`.${cls} g.parking-space[data-number="${nr}"]{--pk:var(--pk-sel)}`));
  if (o.pindNr != null) r.push(`.${cls} g[data-unit="${o.pindNr}"] .unit-label{fill:#fff;font-size:9.5px;font-weight:800}.${cls} g[data-unit="${o.pindNr}"] .door-mark{stroke:#fcca29;stroke-width:1.8}`);
  return `<div class="pk-host ${cls} ${o.edit ? "pk-edit" : "pk-ro"}" data-obj="${objId}"><style>${r.join("")}</style>${s}</div>`;
}
/* v660: register kiipidena (tsooni kaupa) — sama olekuvärvistik kui plaanil; klõpsatav element kannab data-number */
function parkKiibidHTML(objId, o = {}) {
  const reg = parkReg(objId) || [], sel = o.valitud || [], hoive = o.hoive || new Map(), gr = new Map();
  if (!reg.length) return "";
  reg.forEach(k => { const t = k.tsoon || ""; if (!gr.has(t)) gr.set(t, []); gr.get(t).push(k); });
  const kiip = (k) => { const h = hoive.get(k.nr), v = sel.includes(k.nr) ? "pk-sel" : h ? PARK_TOON[h.olek] || "pk-ren" : "";
    const tt = [`Koht ${k.nr}`, k.tsoon, k.tyyp !== "tavaline" ? parkTyypNimi(k.tyyp) : "", k.uld ? "reserv" : "", h ? h.olek + (h.kes ? " · " + h.kes : "") : "vaba"].filter(Boolean).join(" · ");
    return `<button type="button" class="pk-k${k.tyyp !== "tavaline" ? " t-" + k.tyyp : k.uld ? " t-reserv" : ""}" data-number="${k.nr}"${v ? ` style="--pk:var(--${v})"` : ""} title="${escH(tt)}">${k.nr}</button>`; };
  return `<div class="pk-host pk-kiibid ${o.edit ? "pk-edit" : "pk-ro"}" data-obj="${objId}">${[...gr].map(([t, ks]) =>
    `<div class="pk-grp">${gr.size > 1 || t ? `<div class="pk-grp-h">${escH(t || "Tsoonita")} <span>${ks.length}</span></div>` : ""}<div class="pk-kk">${ks.map(kiip).join("")}</div></div>`).join("")}</div>`;
}
const PARK_KLIKK = "g.parking-space, .pk-k";
const parkLegend = (withSel = true) => `<div class="pk-leg">
  ${withSel ? `<span><i style="--pk:var(--pk-sel)"></i>Valitud</span>` : ""}<span><i></i>Vaba</span>
  <span><i style="--pk:var(--pk-off)"></i>Pakkumises</span>
  <span><i style="--pk:var(--pk-ren)"></i>Üüritud</span><span><i style="--pk:var(--pk-pind)"></i>Vaba pinna koht</span>
  <span><i style="--pk:var(--pk-ev)"></i>Elektriauto</span><span><i style="--pk:var(--pk-com)"></i>Reserv</span><span><i style="--pk:var(--pk-out)"></i>Kasutusest väljas</span></div>`;
/* dokumendi kohad + soovitud arv + õigused */
function parkDoc(kind, id) {
  const doc = kind === "o" ? DB.offerById(id) : DB.leaseById(id); if (!doc) return null;
  const sp = DB.spaceById(kind === "o" ? (doc.spaceIds || [])[0] : doc.spaceId); if (!sp) return null;
  const objId = parkObjOfSpace(sp);
  const vaade = kind === "o" && isClient() ? offerSentView(doc) : doc;
  const kohad = kind === "o" ? offerParkKohad(vaade) : ((doc.tehing || {}).parkKohad || []);
  const vaikimisi = kind === "o" ? (doc.spaceIds || []).map(DB.spaceById).filter(Boolean).flatMap(x => pinnaKohad(x, offerParking(doc, x))) : pinnaKohad(sp);
  const soov = kind === "o" ? offerTotals(vaade).parking : ((doc.tehing || {}).parkimine || 0);
  const muuta = !isClient() && (kind === "o"
    ? ["Mustand", "Kliendi ettepanek"].includes(doc.staatus)   /* sama mis canEditPrice — saadetud pakkumine muutub uue versiooniga */
    : (["Mustand V1", "Saadetud"].includes(doc.staatus) || (lepSigned(doc) && !lepArh(doc) && !doc.sulgemine)));
  return { doc, sp, objId, kohad: kohad.slice(), soov, muuta, vahetus: kind === "l" && lepSigned(doc), vaikimisi };
}
/* Lisa 2 vaade (modaalis): plaan valitud kohtadega + nimekiri; üürileandjal „Muuda kohti" */
window.openParkLisa = (kind, id) => {
  const d = parkDoc(kind, id); if (!d) return;
  pdfKind("Lisa 2 · parkimiskohad"); pdfMax(true);
  document.getElementById("pdftitle").textContent = `Lisa 2 · Parkimiskohad · ${d.doc.id}`;
  const fr = document.getElementById("pdfframe"), ht = document.getElementById("pdfhtml");
  fr.style.display = "none"; fr.src = "about:blank";
  document.getElementById("pdfopen").style.display = "none";
  const hist = kind === "l" ? (d.doc.parkAjalugu || []) : [];
  ht.innerHTML = `<div class="pk-lisa">
    <div class="pk-top"><div><div class="overline">${escH(objektOf(d.sp).nimi)} · ${escH(objektOf(d.sp).ehr.aadress)}</div>
      <div class="pk-h">${d.kohad.length ? `Parkimiskohad nr ${parkNrTxt(d.kohad)}` : "Parkimiskohad on määramata"}</div>
      <div class="muted pk-s">${d.soov} ${d.soov === 1 ? "koht" : "kohta"} · ${escH(d.sp.nimi)}${d.kohad.length && d.kohad.length !== d.soov ? ` · plaanil ${d.kohad.length}` : ""}</div></div>
      ${d.muuta ? `<button class="btn btn-primary btn-sm" onclick="parkPick('${kind}','${d.doc.id}')">${d.kohad.length ? (d.vahetus ? "Vaheta kohti" : "Muuda kohti") : "Määra kohad"}</button>` : ""}</div>
    ${parkPlaanHTML(d.objId, { valitud: d.kohad, pindNr: d.sp.nr })}
    ${hist.length ? `<div class="pk-hist"><div class="overline">Kohtade ajalugu</div>${hist.slice().reverse().map(h => `<div class="pk-hr"><span class="mono">${escH(h.aeg)}</span><span>nr ${parkNrTxt(h.vana) || "—"} → <b>nr ${parkNrTxt(h.uus)}</b></span><span class="muted">${escH(h.autor || "")}</span></div>`).join("")}</div>` : ""}
  </div>`;
  ht.style.display = "block";
  document.getElementById("pdfmodal").classList.add("open");
};
/* v555: ÜLDINE kohtade valija (modaal) — siht = kohustuslik arv (vahetus) või null (arv tuleb valikust);
   onSave(sel) otsustab, mis valikuga tehakse (salvestus dokumenti VÕI ettepaneku väli läbirääkimisel) */
function parkPickUI(o) {
  if (!parkOn(o.objId)) { toast("Hoonel pole parkimiskohti registris"); return; }
  let sel = (o.valitud || []).slice();
  const siht = o.siht;   /* null = vaba arv */
  pdfKind(o.kind || "Parkimiskohad · valik plaanil"); pdfMax(true);
  document.getElementById("pdftitle").textContent = o.title || "Parkimiskohad";
  const fr = document.getElementById("pdfframe"), ht = document.getElementById("pdfhtml");
  fr.style.display = "none"; fr.src = "about:blank";
  document.getElementById("pdfopen").style.display = "none";
  const draw = () => {
    const ok = siht == null || !o.vahetus || sel.length === siht;
    ht.innerHTML = `<div class="pk-lisa">
      <div class="pk-top"><div>
        <div class="pk-h">${o.pealkiri || (siht == null ? "Vali kohad" : `Vali ${siht} ${siht === 1 ? "koht" : "kohta"}`)} <span class="pk-cnt ${siht == null || sel.length === siht ? "ok" : ""}">${siht == null ? `${sel.length} ${sel.length === 1 ? "koht" : "kohta"}` : `${sel.length} / ${siht}`}</span></div>
        <div class="muted pk-s">${sel.length ? `Valitud nr ${parkNrTxt(sel)}` : parkPlaaniga(o.objId) ? "Klõpsa plaanil vabadel kohtadel" : "Klõpsa vabadel kohtadel"}${(m => m ? " · " + m : "")(o.markus && o.markus(sel))}</div></div>
        <div class="wrap-actions">
          ${(o.vaikimisi || []).length ? `<button class="btn btn-ghost btn-sm" id="pk-vaike" title="Pinna kohad: ${parkNrTxt(o.vaikimisi)}">Pinna kohad</button>` : ""}
          ${siht != null ? `<button class="btn btn-ghost btn-sm" id="pk-auto">${parkPlaaniga(o.objId) ? "Vali lähimad vabad" : "Vali vabad"}</button>` : ""}
          <button class="btn btn-ghost btn-sm" id="pk-clear" ${sel.length ? "" : "disabled"}>Tühjenda</button>
          <button class="btn btn-primary btn-sm" id="pk-save" ${ok ? "" : "disabled"}>${o.nupp || "Salvesta kohad"}</button></div></div>
      ${parkPlaanHTML(o.objId, { valitud: sel, hoive: o.hoive, pindNr: o.pindNr, edit: true })}
      ${parkLegend()}
    </div>`;
    ht.querySelectorAll(PARK_KLIKK).forEach(g => g.onclick = () => {
      const nr = +g.dataset.number, h = o.hoive.get(nr);
      if (h && !h.pehme && !h.vaba && !sel.includes(nr)) { toast(`Koht ${nr} · ${h.olek.toLowerCase()}${h.kes ? " · " + h.kes : ""}`); return; }
      if (h && h.pehme && !sel.includes(nr)) toast(`Koht ${nr} on määratud: ${h.kes} — määrad ümber`);
      if (!sel.includes(nr) && o.vahetus && sel.length >= siht) { toast("Eemalda enne üks koht — kehtival lepingul jääb arv samaks"); return; }
      sel = sel.includes(nr) ? sel.filter(x => x !== nr) : [...sel, nr];
      draw();
    });
    const q = (x) => ht.querySelector(x);
    q("#pk-clear").onclick = () => { sel = []; draw(); };
    const vk = q("#pk-vaike"); if (vk) vk.onclick = () => { sel = o.vaikimisi.slice(); draw(); };
    const au = q("#pk-auto");
    if (au) au.onclick = () => {
      sel = sel.slice(0, siht).concat(parkLahimad(o.objId, o.pindNr, Math.max(0, siht - sel.length), o.hoive, sel));
      draw();
    };
    q("#pk-save").onclick = () => o.onSave(sel.slice().sort((a, b) => a - b));
  };
  ht.style.display = "block"; draw();
  document.getElementById("pdfmodal").classList.add("open");
}
/* dokumendi kohtade valik ja salvestus (pakkumise mustand, lepingu mustand/läbirääkimine, kehtiva vahetus) */
