  document.getElementById("pdftitle").textContent = `${l.id} · ${sp.nimi} · ettepanek`;
  const fr = document.getElementById("pdfframe"), ht = document.getElementById("pdfhtml");
  fr.style.display = "none"; fr.src = "about:blank"; document.getElementById("pdfopen").style.display = "none";
  const uued = kohad.filter(n => !praegu.includes(n)), ara = praegu.filter(n => !kohad.includes(n));
  ht.innerHTML = `<div class="pk-lisa"><div class="pk-top"><div>
      <div class="pk-h">Ettepanek: kohad nr ${parkNrTxt(kohad)}</div>
      <div class="muted pk-s">${kohad.length} ${kohad.length === 1 ? "koht" : "kohta"}${uued.length ? ` · lisandub nr ${parkNrTxt(uued)}` : ""}${ara.length ? ` · loobutakse nr ${parkNrTxt(ara)}` : ""}</div></div></div>
    ${parkPlaanHTML(objId, { valitud: kohad, pindNr: sp.nr })}</div>`;
