window.addEventListener("hashchange", () => { if (!/^#?\/?$/.test(location.hash)) DASH_KOIK = false; });
/* ===== AVALEHT LÕPP ===== */

/* ===== ÜHENDAMINE (demo 4) · abifunktsioonid, mida AI kasutab — päris kujul tulevad oma etapis (kuupäevad v643, indeks v642, seaded v637) ===== */
const P6_THI = 0.034;   /* Statistikaameti THI 12 kuu muutus — viimane teadaolev */
const p6PctM = (p) => `${p >= 0 ? "+" : "−"}${(Math.abs(p) * 100).toFixed(1).replace(/\.0$/, "").replace(".", ",")} %`;
function p6Meetod(txt) {
  const t = String(txt || "");
  if (!t.trim() || /puudub|ei indekseerita|indekseerimiseta/i.test(t)) return { liik: "ei", pct: 0, silt: "ei indekseerita" };
  if (/THI|tarbijahinna/i.test(t)) return { liik: "thi", pct: P6_THI, silt: `THI ${p6PctM(P6_THI)}` };
  const m = t.match(/(\d+(?:[.,]\d+)?)\s*%/), pct = m ? parseFloat(m[1].replace(",", ".")) / 100 : 0.03;
  return { liik: "fix", pct, silt: `fikseeritud ${p6PctM(pct).replace(/^\+/, "")}` };
}
/* kolleegi demost (demo 4) ühendatud 29.09 — Plokk 4 · 4.4: iga saatmine on kiri (kellele · teema · tekst mallist), kohaletoimetamine, põrge */
function p7Sisu(t) {
  let s = String(t || "").replace(/\r/g, "").trim();
  s = s.replace(/^(tere|hea|lugupeetud|hei)\b[^\n]*\n+/i, "");
  s = s.replace(/\n+(parimate soovidega|lugupidamisega|tervitades|parimat|heade soovidega)[\s\S]*$/i, "");
  return s.trim();
}
/* --- abid --- */
const p4PaevadKuni = (ee) => ee ? paevadeVahe(ee) : 0;   /* v643: üks lugeja */
const p4PaevadMoodas = (aeg) => aeg ? Math.max(0, -paevadeVahe(aeg)) : 0;   /* v643: üks lugeja */
const p4Periood = (kuud) => !kuud ? "—" : kuud % 12 === 0 ? `${kuud / 12} ${kuud === 12 ? "aasta" : "aastat"}` : `${kuud} kuud`;
const p4Eesnimi = (nimi) => String(nimi || "").trim().split(/\s+/)[0] || "";
const p4Init = (nimi) => String(nimi || "?").trim().split(/\s+/).map(x => x[0]).join("").slice(0, 2).toUpperCase();
function p4Aeg(s) { const [d, t] = String(s || "").split(" "); if (!d) return ""; return d === TODAY_EE ? `täna${t ? " " + t : ""}` : `${d.slice(0, 5)}${t ? " " + t : ""}`; }
const p4Allkiri = () => `Parimate soovidega\nTarmo Sepp\n${ACCOUNT.landlord.nimi}`;

/* --- 4.4 kirjad: doc.kirjad = [{ id, liik, teema, tekst, saaja {nimi, epost}, aeg, olek kohal|porkus, kohal, avatud, pohjus, nr }] --- */
const P4_TYPO = /@(gmial|gmai|gnail|hotmial|hotmal|outlok|outloo|yaho|yahooo)\.[a-z]+$/i;
const p4Kirjad = (doc) => Array.isArray(doc && doc.kirjad) ? doc.kirjad : [];
const p4Viimane = (doc) => { const K = p4Kirjad(doc); return K[K.length - 1] || null; };
function p4Porkub(doc, ep) {
  const e = String(ep || "").trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(e) || P4_TYPO.test(e) || /\.invalid$/.test(e)) return true;
  /* sama aadress, mis juba põrkus, põrkub uuesti — parandada tuleb aadressi */
  return p4Kirjad(doc).some(k => k.olek === "porkus" && String(k.saaja.epost).toLowerCase() === e);
}
function p4PorkePohjus(ep) { const d = String(ep || "").split("@")[1] || "";
  return !d || !/\./.test(d) ? "aadress on vigane" : P4_TYPO.test(ep) ? `domeeni ${d} ei leitud, võimalik trükiviga` : `postkasti ${ep} ei leitud`; }
function p4Saaja(kind, doc) {
  if (doc.kiriAadress) return Object.assign({}, doc.kiriAadress);
  const cl = DB.clientById(doc.clientId) || {};
  if (kind === "o") { const ct = offerContact(doc, cl); return { nimi: ct.nimi || cl.kontakt || cl.nimi, epost: ct.epost || cl.epost || "" }; }
  const k = doc.kontakt || {}; return { nimi: k.nimi || cl.kontakt || cl.nimi, epost: k.epost || cl.epost || "" };
}
function p4Kiri(doc, k) {
  const aeg = NOW_EE(), ep = String((k.saaja && k.saaja.epost) || "").trim(), porkus = p4Porkub(doc, ep);
  const kiri = Object.assign({ id: "K" + Date.now().toString(36) + p4Kirjad(doc).length, aeg, olek: porkus ? "porkus" : "kohal",
    kohal: porkus ? null : aeg, avatud: null, pohjus: porkus ? p4PorkePohjus(ep) : null }, k, { saaja: { nimi: k.saaja.nimi, epost: ep } });
  if (!Array.isArray(doc.kirjad)) doc.kirjad = [];
  doc.kirjad.push(kiri);
  AUDIT.unshift({ aeg, autor: "Tarmo Sepp", tegevus: `${doc.id}: kiri „${k.teema}" → ${k.saaja.nimi} <${ep}> — ${porkus ? "ei jõudnud kohale" : "kohale toimetatud"}.` });
  return kiri;
}
const p4OlekTx = (k) => !k ? "" : k.olek === "porkus" ? "kiri ei jõudnud kohale" : `kohale toimetatud${k.avatud ? ` · avas lingi ${p4Aeg(k.avatud)}` : ""}`;
/* klient avas lingi — esimese osapoole sündmus (tema klõps lingil), mitte e-kirja jälgimispiksel */
function p4Avas(doc) { const k = p4Viimane(doc); if (!k || k.olek !== "kohal" || k.avatud) return; k.avatud = NOW_EE();
  AUDIT.unshift({ aeg: k.avatud, autor: `${(k.saaja && k.saaja.nimi) || "Lingi omanik"} (üürnik)`, tegevus: `${doc.id}: üürnik avas lingi (kiri „${k.teema}").` });   /* v793: link holder */
  DB.save(); }

/* kirjade mallid */
function p4PakkumiseKiri(o, liik, vastus) {
  const cl = DB.clientById(o.clientId) || {}, ct = offerContact(o, cl), t = offerTotals(o), vat = OBJEKT.kaibemaksugaMaksustatud;
  const pinnad = t.spaces.map(s => s.nimi).join(", "), hoone = objektOf(t.spaces[0]).nimi, m2 = t.spaces.reduce((s, x) => s + x.yyripind, 0);
  const tere = `Tere${p4Eesnimi(ct.nimi || cl.kontakt) ? ", " + p4Eesnimi(ct.nimi || cl.kontakt) : ""}!`;
  if (liik === "meeldetuletus") { const d = p4PaevadKuni(o.kehtivKuni);
    return { teema: `Meeldetuletus: hinnapakkumine kehtib kuni ${o.kehtivKuni}`,
      tekst: `${tere}\n\nTuletan meelde, et hinnapakkumine (${pinnad}, ${hoone}) kehtib veel ${d > 0 ? p4P(d) : "täna"} — kuni ${o.kehtivKuni}. Kui soovite midagi muuta, kirjutage otse pakkumise juures.\n\n${p4Allkiri()}` }; }
  /* v643 (3a): vastusest tervitus ja allkiri välja (mall lisab); muutmata pakkumise vastus ei ütle „uuendatud" */
  if (liik === "pakkumine-uus") return { teema: `Uuendatud hinnapakkumine · ${pinnad}, ${hoone}`,
    tekst: `${tere}\n\n${p7Sisu(vastus) || "Uuendasime pakkumist teie ettepaneku põhjal."}\n\nUuendatud pakkumine on samal lingil — kehtib kuni ${o.kehtivKuni}.\n\n${p4Allkiri()}` };
  if (liik === "pakkumine-vastus") return { teema: `Vastus teie ettepanekule · ${pinnad}, ${hoone}`,
    tekst: `${tere}\n\n${p7Sisu(vastus) || "Vaatasime teie ettepaneku üle."}\n\nPakkumine kehtib endiselt samal lingil — kuni ${o.kehtivKuni}.\n\n${p4Allkiri()}` };
  return { teema: `Hinnapakkumine · ${pinnad}, ${hoone}`,
    tekst: `${tere}\n\nSaadan teile hinnapakkumise: ${pinnad} (${eur(m2, 1)} m²), üür ${eur(t.astmeline ? t.avgSum : t.rentSum)} €${vat ? " + KM" : ""} kuus, periood ${p4Periood(o.pikkusKuud)}. Pakkumine kehtib kuni ${o.kehtivKuni}.\n\nLingi kaudu näete pakkumist ilma kontota ning saate selle kohe aktsepteerida või soovida muudatusi.\n\n${p4Allkiri()}` };
}
function p4LepinguKiri(l) {
  const cl = DB.clientById(l.clientId) || {}, sp = { nimi: lepPindNimi(l), yyripind: lepM2(l) }, f = ensureTehing(l), s = p4Saaja("l", l);
  return { teema: `Üürilepingu mustand · ${sp.nimi}, ${objektOf(DB.spaceById(l.spaceId)).nimi}`,
    tekst: `Tere${p4Eesnimi(s.nimi) ? ", " + p4Eesnimi(s.nimi) : ""}!\n\nSaadan üürilepingu mustandi: ${sp.nimi} (${eur(sp.yyripind, 1)} m²), algus ${isoToEE(f.algus)}, üür ${eur(lepKuus(l))} €${OBJEKT.kaibemaksugaMaksustatud ? " + KM" : ""} kuus.\n\nLingi kaudu saate lepingu läbi vaadata ja punktide juures kommenteerida. Kui kõik sobib, aktsepteerite lepingu ja see liigub allkirjastamisse.\n\n${p4Allkiri()}` };
}
/* meie voor: üürileandja saadab vastused ühe kirjana */
function p4VastuseKiri(l, v) {
  const s = p4Saaja("l", l), n = (v.pids || []).length, ref = (v.refid || []).join(", ");
  return { teema: `Vastused teie märkustele · ${l.id}`,
    tekst: `Tere${p4Eesnimi(s.nimi) ? ", " + p4Eesnimi(s.nimi) : ""}!\n\nVastasime ${n === 1 ? "teie märkusele" : `teie ${n} märkusele`}${ref ? ` (${ref})` : ""}. Vastused ja muudatused näete lepingu juures samal lingil — kui kõik sobib, saate lepingu kohe allkirjastada.\n\n${p4Allkiri()}` };
}
/* ühekordne järeltäide: juba saadetud dokumentidel pole kirjade kirjeid (enne v640) — tekivad kohale toimetatuna.
   Demo seeme: üks põrganud pakkumise kiri (vale domeen), et põrke ja parandamise voog oleks näha. */
const P4_NAIDE_PORGE = { taeva: "PAK-2026-011" };
function p4Taida() {
  let n = 0;
  OFFERS.forEach(o => {
    if (Array.isArray(o.kirjad) || ["Mustand", "Tühistatud"].includes(o.staatus)) return;
    const s = p4Saaja("o", o), v = offerVers(o), aeg = (v[0] && v[0].aeg) || `${o.loodud} 10:00`, T = p4PakkumiseKiri(o, "pakkumine");
    const pork = P4_NAIDE_PORGE[DB.COMPANY_ID] === o.id && o.staatus === "Saadetud";
    o.kirjad = [{ id: "K1-" + o.id, liik: "pakkumine", teema: T.teema, tekst: T.tekst, saaja: s, aeg, olek: pork ? "porkus" : "kohal", kohal: pork ? null : aeg,
      avatud: null, pohjus: pork ? `domeeni ${String(s.epost).split("@")[1] || ""} ei leitud` : null, nr: 1 }];
    v.slice(1).forEach(x => { const T2 = p4PakkumiseKiri(o, "pakkumine-uus", x.vastus);
      o.kirjad.push({ id: `K${x.nr}-${o.id}`, liik: "pakkumine-uus", teema: T2.teema, tekst: T2.tekst, saaja: s, aeg: x.aeg, olek: "kohal", kohal: x.aeg, avatud: null, pohjus: null, nr: x.nr }); });
    n++;
  });
  LEASES.forEach(l => {
    if (Array.isArray(l.kirjad) || l.staatus === "Mustand V1") return;
    const s = p4Saaja("l", l), V = l.versioonid || [], T = p4LepinguKiri(l);
    const v0 = (l.voorud || []).find(v => v.v1), aeg = (v0 && v0.saadetud) || (V[0] && V[0].aeg) || (l.v1 && l.v1.aeg) || l.saadetud || `${l.algus} 10:00`;
    l.kirjad = [{ id: "K1-" + l.id, liik: "leping", teema: T.teema, tekst: T.tekst, saaja: s, aeg, olek: "kohal", kohal: aeg, avatud: null, pohjus: null, nr: 1 }];
    (l.voorud || []).filter(v => v.kes === "operaator" && !v.v1).forEach(v => { const T2 = p4VastuseKiri(l, v);
      l.kirjad.push({ id: `K${v.nr}-${l.id}`, liik: "vastus", teema: T2.teema, tekst: T2.tekst, saaja: s, aeg: v.saadetud, olek: "kohal", kohal: v.saadetud, avatud: null, pohjus: null, nr: v.nr }); });
    n++;
  });
  if (n) DB.save();
}

/* --- 4.4 saatmine (v641, kasutaja: kinnituskaart „ei too suurt väärtust" — võeti ära): kiri läheb kohe malli järgi,
       kiri ja kohaletoimetamise olek jäävad dokumendi juurde; põrke korral parandatakse aadress otse juhtkaardil --- */
/* pakkumine: esimene saatmine · uuesti saatmine · meeldetuletus. teg(kirjuta, porkub, saaja) teeb dokumendi muutuse (vaate mutate) */
function p4SaadaPakkumine(o, liik, vastus, teg) {
  const T = p4PakkumiseKiri(o, liik, vastus), saaja = p4Saaja("o", o), pork = p4Porkub(o, saaja.epost);
  const kirjuta = () => p4Kiri(o, { liik, teema: T.teema, tekst: T.tekst, saaja, nr: liik === "pakkumine" ? 1 : undefined });
  if (teg) { teg(kirjuta, pork, saaja); return; }
  kirjuta(); DB.save(); toast(pork ? `Kiri ei jõudnud kohale — kontrolli aadressi ${saaja.epost}` : `Meeldetuletus saadetud · ${saaja.nimi} · kohale toimetatud`); router();
}
/* leping: esimene saatmine üürnikule */
function p4SaadaLeping(l, teg) {
  const T = p4LepinguKiri(l), saaja = p4Saaja("l", l), pork = p4Porkub(l, saaja.epost);
  teg(() => p4Kiri(l, { liik: "leping", teema: T.teema, tekst: T.tekst, saaja, nr: 1 }), pork, saaja);
}
/* põrge → sama kiri parandatud aadressile; aadressi väli ja nupp on juhtkaardil */
function p4PorgeVorm(kind, id, k) {
  return `<div class="p4-pv"><label class="p4-pv-l" for="p4-pv-ep">Õige aadress</label>
      <div class="p4-pv-r"><input id="p4-pv-ep" type="email" class="ce-in" value="${escH(k.saaja.epost)}" autocomplete="off" spellcheck="false"
        onkeydown="if (event.key === 'Enter') { event.preventDefault(); p4Uuesti('${kind}', '${id}'); }">
      <button class="btn btn-primary btn-sm" onclick="p4Uuesti('${kind}', '${id}')">Saada uuesti<span class="bic">${I.arrow}</span></button></div></div>`;
}
window.p4Uuesti = (kind, id) => {
  const doc = kind === "o" ? DB.offerById(id) : lepLive(DB.leaseById(id)); if (!doc) return;
  const k = p4Viimane(doc); if (!k) return;
  const inp = document.getElementById("p4-pv-ep"), ep = String((inp && inp.value) || k.saaja.epost).trim();
  if (!/^[^@\s]+@[^@\s]+$/.test(ep)) { toast("Kontrolli e-posti aadressi — kujul nimi@ettevote.ee"); if (inp) inp.focus(); return; }
  const saaja = { nimi: k.saaja.nimi, epost: ep };
  if (ep !== k.saaja.epost) doc.kiriAadress = saaja;
  const uus = p4Kiri(doc, { liik: k.liik, teema: k.teema, tekst: k.tekst || "", saaja, nr: k.nr });
  DB.save(); toast(uus.olek === "porkus" ? `Kiri ei jõudnud jälle kohale — ${uus.pohjus}` : `Saadetud uuesti · ${saaja.nimi} · kohale toimetatud`); router();
};
window.p4Meenuta = (id) => { const o = DB.offerById(id); if (o) p4SaadaPakkumine(o, "meeldetuletus"); };
window.p4Vasta = () => { const p = document.getElementById("nego-panel"); if (!p) return;
  p.scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "start" });
  const t = document.getElementById("op-reply"); if (t) setTimeout(() => t.focus({ preventScroll: true }), 320); };

/* kolleegi demost (demo 4) ühendatud 29.09 — Plokk 4 · 4.3 versioonid (V1 = esimene saatmine, iga üürileandja vooru vastus = uus versioon) ja 4.2 ajalugu */
const labiLyh = (t, n) => { t = String(t || ""); return t.length > n ? t.slice(0, n - 1).replace(/\s+\S*$/, "") + "…" : t; };
const p4Snap = (l, nr, aeg) => ({ silt: "V" + nr, aeg: aeg || NOW_EE(), tehing: JSON.parse(JSON.stringify(l.tehing || {})),
  tekst: Object.fromEntries((l.punktid || []).map(p => [p.id, p.tekst])), eri: eriKinni(l).map(e => ({ id: e.id, tekst: e.tekst })),
  ettepanekud: (l.arutelud || []).filter(c => c.staatus === "Ootab kinnitust" && c.ettepanek).map(c => Object.assign({ punktId: c.punktId }, c.ettepanek)) });
/* varem saadetud lepingud: V1 esimese saatmise hetktõmmisest (l.v1) */
function p4VerTaida() {
  let n = 0;
  LEASES.forEach(l => { if (Array.isArray(l.versioonid) || l.staatus === "Mustand V1" || !(l.v1 || l.saadetud)) return;
    const V = p4Snap(l, 1, (l.v1 && l.v1.aeg) || l.saadetud); if (l.v1 && l.v1.tekst) V.tekst = Object.assign({}, l.v1.tekst);
    l.versioonid = [V]; n++; });
  if (n) DB.save();
}
/* --- 4.3 lepingu versioonid: iga saadetud voor eraldi, erinevus eelmisest sõnatasemel --- */
const P4_FAKTID = ["hind", "kuud", "algus", "tagatisKuud", "parkimine", "otstarve", "erisused"];
function p4VerDiff(l, a, b) {
  const A = a.tehing || {}, B = b.tehing || {};
  const faktid = P4_FAKTID.filter(key => JSON.stringify(A[key]) !== JSON.stringify(B[key]) && (A[key] != null || B[key] != null))
    .map(key => ({ lbl: FACT_LABELS[key] || key, vana: A[key] == null ? "—" : faktTxt(key, A[key]), uus: B[key] == null ? "—" : faktTxt(key, B[key]) }));
  const ta = a.tekst || {}, tb = b.tekst || {};
  const punktid = Object.keys(tb).filter(id => ta[id] != null && ta[id] !== tb[id]).map(id => ({ p: punktById(l, id) || { id }, vana: ta[id], uus: tb[id] }))
    .filter(x => x.p.osa !== "eri");
  const eA = new Map((a.eri || []).map(e => [e.id, e.tekst])), eB = new Map((b.eri || []).map(e => [e.id, e.tekst]));
  const eri = [...eB].filter(([id, t]) => eA.get(id) !== t).map(([id, t]) => ({ id, vana: eA.get(id) || null, uus: t }))
    .concat([...eA].filter(([id]) => !eB.has(id)).map(([id, t]) => ({ id, vana: t, uus: null })));
  return { faktid, punktid, eri };
}
function p4VerKiri(l, nr) {
  const k = p4Kirjad(l).filter(x => x.nr === nr && x.tekst).pop(); return k ? k.tekst : "";   /* v643 (3b): viimane (uuesti saadetud) kiri */
}
function p4VerHTML(l, sel) {
  const V = Array.isArray(l.versioonid) ? l.versioonid : [];
  const tabs = `<div class="p4-vt" role="group" aria-label="Versioon">${V.map(v => `<button type="button" class="${sel === v.silt ? "on" : ""}" data-p4v="${v.silt}">${v.silt}</button>`).join("")}
      <button type="button" class="${sel === "kokku" ? "on" : ""}" data-p4v="kokku">Kokku V1 → praegu</button></div>`;
  const pea = `<div class="ld-top"><div><div class="doc-title">Versioonid</div>
      <div class="doc-sub">${l.id} · iga saadetud voor on külmutatud — võrdlus eelmisega sõnatasemel</div></div></div>`;
  if (sel === "kokku") return `<div class="ld p4-ver">${pea}${tabs}<div class="p4-ver-kokku">${lepDiffHTML(l)}</div></div>`;
  const i = Math.max(0, V.findIndex(v => v.silt === sel)), v = V[i], nr = i + 1; if (!v) return `<div class="ld p4-ver">${pea}${tabs}<div class="ld-empty">${I.info} Leping pole veel saadetud — versioonid tekivad saatmisel.</div></div>`;
  const k = p4Kirjad(l).filter(x => x.nr === nr).pop(), kiri = p4VerKiri(l, nr);   /* v643 (3b) */
  const meta = `<div class="p4-vm"><b>${v.silt}</b><span>saadetud ${escH(String(v.aeg || ""))}</span>${k ? `<span>${escH(k.saaja.nimi)}</span>${isClient() ? "" : `<span>${p4OlekTx(k)}</span>`}` : ""}</div>`;
  const kiriHTML = kiri ? `<details class="p4-vk"${i ? " open" : ""}><summary>Kiri · ${escH((k && k.teema) || (i ? "vastus" : "leping"))}</summary><div class="p4-vk-tx">${escH(kiri)}</div></details>` : "";
  if (!i) return `<div class="ld p4-ver">${pea}${tabs}${meta}${kiriHTML}<div class="ld-same">Esimene saadetud versioon — võrdlusalus kõigile järgmistele voorudele.</div></div>`;
  const d = p4VerDiff(l, V[i - 1], v), ep = v.ettepanekud || [];
  const faktid = d.faktid.length ? `<div class="ld-item"><ul class="od-facts">${d.faktid.map(x => `<li><span class="lbl">${escH(x.lbl)}</span><span class="val">${x.vana !== "—" ? `<del>${escH(x.vana)}</del><span class="od-arrow">→</span>` : ""}<b>${escH(x.uus)}</b></span></li>`).join("")}</ul></div>` : "";
  const punktid = d.punktid.map(x => `<div class="ld-item"><div class="ld-h"><span class="mono ld-ref">${escH(punktRefD(l, x.p) || x.p.id)}</span><b>${escH(punktTitle(l, x.p) || "")}</b></div>
      <div class="df-body">${diffHTML(x.vana, x.uus)}</div></div>`).join("");
  const eri = d.eri.map(x => `<div class="ld-item"><div class="ld-h"><span class="mono ld-ref">Lisa 3</span><b>Eritingimus${x.uus && !x.vana ? " lisatud" : !x.uus ? " eemaldatud" : " muudetud"}</b></div>
      <div class="df-body">${x.vana && x.uus ? diffHTML(x.vana, x.uus) : x.uus ? `<ins class="df-ins">${escH(x.uus)}</ins>` : `<del class="df-del">${escH(x.vana)}</del>`}</div></div>`).join("");
  const epHTML = ep.length ? `<div class="overline ld-sec">Ettepanekud selles voorus · jõustuvad üürniku kinnitusel</div>
      ${ep.map(e => { const p = punktById(l, e.punktId) || {}; return `<div class="ld-item"><div class="ld-h"><span class="mono ld-ref">${escH(punktRefD(l, p) || "")}</span><b>${escH(punktTitle(l, p) || "")}</b></div>
        <div class="ld-body">${e.fKey ? `${escH(FACT_LABELS[e.fKey] || "Väärtus")}: <del>${escH(e.vanaTxt || "")}</del> → <b>${escH(e.uusTxt || "")}</b>` : escH(labiLyh(e.tekst || e.uusTxt || "", 220))}</div></div>`; }).join("")}` : "";
  const muut = faktid || punktid || eri;
  return `<div class="ld p4-ver">${pea}${tabs}${meta}${kiriHTML}
      <div class="overline ld-sec">Mis muutus ${V[i - 1].silt} → ${v.silt}</div>
      ${muut ? faktid + punktid + eri : `<div class="ld-same">Lepingu tekst jäi samaks — selle vooru muudatused ootasid üürniku kinnitust (vt all).</div>`}
      ${epHTML}</div>`;
}
window.p4VerAva = (id, silt) => {
  const l = DB.leaseById(id); if (!l) return;
  const V = Array.isArray(l.versioonid) ? l.versioonid : [];
  let sel = silt || (V.length > 1 ? V[V.length - 1].silt : V.length ? V[0].silt : "kokku");
  pdfKind("Leping · versioonid");
  document.getElementById("pdftitle").textContent = `Versioonid · ${l.id}`;
  const fr = document.getElementById("pdfframe"), ht = document.getElementById("pdfhtml");
  fr.style.display = "none"; fr.src = "about:blank";
  document.getElementById("pdfopen").style.display = "none";
  const draw = () => { ht.innerHTML = p4VerHTML(l, sel); ht.querySelectorAll("[data-p4v]").forEach(b => b.onclick = () => { sel = b.dataset.p4v; draw(); });
    bindDiffTabs(ht, draw); };
  ht.style.display = "block"; draw();
  document.getElementById("pdfmodal").classList.add("open");
};
