/* süsteemi koostatud pikenduse mustand on üürnikule nähtamatu, kuni see saadetakse */
const p6RingVaade = (l) => { const r = aktiivneRing(l); return r && isClient() && r.pikendus && r.staatus === "Koostamisel" ? null : r; };

/* ---------- 6.4 pikendus ühe klõpsuga ---------- */
const p6Tahtajaline = (l) => /^\d\d\.\d\d\.\d{4}$/.test(String(l.lopp || ""));
