/* platvormi lepingute tähtajad KEY_DATES-is (indekseerimine, lõpp) — kalender, Avaleht, osapool ja AI näevad sama */
function p6KdSync() {
  for (let i = KEY_DATES.length - 1; i >= 0; i--) if (KEY_DATES[i].p6) KEY_DATES.splice(i, 1);
  LEASES.forEach(l => {
    if (!lepSigned(l) || lepArh(l)) return;
    const cl = DB.clientById(l.clientId) || {}, sp = { nimi: lepPindNimi(l) }, obj = `${l.id} · ${cl.nimi}`, m = p6LepMeetod(l), j = (l.indeks || {}).jargmine;
    if (j && m.liik !== "ei") { const v = p6Kuus(l);
      KEY_DATES.push({ kuupaev: eeToISO(j), tyyp: "Indekseerimine", objekt: obj, margis: "accent", p6: true, info: `${sp.nimi} · ${m.silt} · ${eur(v)} → ${eur(v * (1 + m.pct))} € kuus · rakendub ise, lisa ei teki` }); }
    if (p6Tahtajaline(l) && !(l.lopetamine && l.lopetamine.staatus === "Kinnitatud")) { const r = aktiivneRing(l), pik = r && r.pikendus;
      KEY_DATES.push({ kuupaev: eeToISO(l.lopp), tyyp: "Lepingu lõpp", objekt: obj, margis: pik ? "amber" : "grey", p6: true,
        info: `${sp.nimi} · ${pik ? (r.staatus === "Koostamisel" ? `pikenduse mustand valmis (Lisa ${r.nr}) — saatmata` : `pikendus Lisa ${r.nr} · ${r.staatus.toLowerCase()}`) : l.pikendusLoobutud ? "ei pikendata · planeeri pinna vabanemine" : `pikenduse mustand valmib ${p6PikPaevi()} päeva enne lõppu`}` }); }
  });
}
function p6Sync() {
  try {
    LEASES.forEach(l => { if (!lepSigned(l) || lepArh(l) || p6LepMeetod(l).liik === "ei") return;
      const j = p6IndeksKp(l).find(d => d > DEMO_TODAY); (l.indeks = l.indeks || {}).jargmine = j ? fmtEE(j) : null; });
    p6KdSync();
  } catch (e) { console.error(e); }
}
/* käivitusel („öötöö"): möödunud indekseerimised rakenduvad, lõppevatele lepingutele valmib pikenduse mustand */
function p6Automaatika() {
  let n = 0;
  LEASES.forEach(l => { if (!lepSigned(l) || lepArh(l)) return; n += p6IndeksRakenda(l); if (p6PikOotel(l) && p6PikValmista(l, true)) n++; });
  if (n) DB.save();
  p6Sync();
}

/* ---------- 6.6 vaikus → „Saada meeldetuletus?" + mustand ---------- */
const p6ViimaneKiri = (doc, liigid, f) => p4Kirjad(doc).filter(k => liigid.includes(k.liik) && (!f || f(k))).slice(-1)[0] || null;
function p6KliTegevus(l) {
  let t = 0;
  (l.arutelud || []).forEach(c => { if (c.algataja === "klient") t = Math.max(t, eeMs(c.aeg)); (c.sonumid || []).forEach(m => { if (m.roll === "klient") t = Math.max(t, eeMs(m.aeg)); }); });
  return t;
}
function p6Vaikus(kind, doc, ring) {
  if (isClient() || !doc) return null;
  const hoia = (ring || doc).meenutaEdasi; if (hoia && parseEE(hoia) > DEMO_TODAY) return null;
  let kiri = null, saaja = null, isik = null;
  if (kind === "o") {
    if (doc.staatus !== "Saadetud" || p4PaevadKuni(doc.kehtivKuni) < 0) return null;
    kiri = p6ViimaneKiri(doc, ["pakkumine", "pakkumine-uus", "pakkumine-vastus", "meeldetuletus"]);
  } else if (kind === "l") {
    doc = lepLive(doc);   /* v805 audit 8: elav leping, arutelud nii nagu operaator neid näeb */
    if (doc.staatus !== "Saadetud" || (doc.voor && doc.voor.kes === "operaator") || lepAruNahtav(doc).some(aruOotabOp)) return null;   /* pall on meil — meeldetuletust pole vaja */
    kiri = p6ViimaneKiri(doc, ["leping", "vastus", "meeldetuletus"], k => !k.lisa && !k.isik);
    if (kiri && p6KliTegevus(doc) > eeMs(kiri.aeg)) return null;
  } else if (kind === "ring") {
    if (!ring || ring.staatus !== "Kinnitamisel") return null;
    kiri = p6ViimaneKiri(doc, ["lisa", "meeldetuletus"], k => k.lisa === ring.nr && !k.isik);
  } else if (kind === "allk") {
    const d = ring || doc; if ((ring ? ring.staatus : doc.staatus) !== "Allkirjastamisel") return null;
    const S = p6Seis(doc, d); if (!S[0].valmis || S[1].valmis) return null;
    isik = S[1].read.filter(r => !r.sig && r.kutse).sort((a, b) => eeMs(a.kutse) - eeMs(b.kutse))[0];
    if (!isik) return null;
    kiri = { aeg: isik.kutse }; saaja = { nimi: isik.nimi, epost: isik.epost };
  }
  if (!kiri || (kiri.olek && kiri.olek !== "kohal")) return null;
  const paevi = p6Moodas(kiri.aeg); if (paevi < p6VaikusPaevi()) return null;
  return { kind, doc, ring, kiri, saaja: saaja || kiri.saaja, paevi, isik };
}
function p6MeenutaMall(v) {
  const d = v.doc, s = v.saaja, tere = `Tere${p4Eesnimi(s.nimi) ? ", " + p4Eesnimi(s.nimi) : ""}!`, saatsin = String(v.kiri.aeg || "").split(" ")[0].slice(0, 5);
  if (v.kind === "o") { const t = offerTotals(d), pinnad = t.spaces.map(x => x.nimi).join(", "), hoone = objektOf(t.spaces[0]).nimi, dk = p4PaevadKuni(d.kehtivKuni);
    return { teema: `Kas pakkumine sobib? · ${pinnad}, ${hoone}`,
      tekst: `${tere}\n\nSaatsin ${saatsin} hinnapakkumise (${pinnad}, ${hoone}). Kas saite sellega tutvuda? Pakkumine kehtib veel ${dk > 0 ? p4P(dk) : "täna"} — kuni ${d.kehtivKuni}.\n\nKui midagi vajab muutmist, kirjutage otse pakkumise juures — vastan kiiresti.\n\n${p4Allkiri()}` }; }
  const sp = { nimi: lepPindNimi(d) }, obj = objektOf(DB.spaceById(d.spaceId));
  if (v.kind === "l") return { teema: `Üürilepingu mustand ootab teie vaadet · ${sp.nimi}, ${obj.nimi}`,
    tekst: `${tere}\n\nSaatsin ${saatsin} üürilepingu ${d.id} mustandi (${sp.nimi}). Kas saite sellega tutvuda? Kui mõni punkt vajab arutamist, kommenteerige otse lepingu juures; kui kõik sobib, aktsepteerige leping ja see liigub allkirjastamisse.\n\n${p4Allkiri()}` };
  if (v.kind === "ring") { const r = v.ring, f = r.faktid.find(x => x.key === "kuud");
    return { teema: `${r.pikendus ? "Lepingu pikendus" : `Lisa ${r.nr}`} ootab teie kinnitust · ${d.id}`,
      tekst: `${tere}\n\nSaatsin ${saatsin} ${r.pikendus ? `pikenduse ettepaneku: Lisa ${r.nr} pikendab üürilepingut ${d.id} kuni ${p6PikLopp(d, f && f.uus)}` : `üürilepingu ${d.id} muudatuse (Lisa ${r.nr})`}. Kas saite sellega tutvuda? Kui kõik sobib, kinnitage lisa lingi kaudu — seejärel allkirjastavad pooled selle Dokobitis.${r.pikendus ? ` Praegune leping lõpeb ${d.lopp}.` : ""}\n\n${p4Allkiri()}` }; }
  const r = v.ring, P = p6Seis(d, r || d)[1], teised = P.read.filter(x => x.sig).map(x => x.nimi);
  return { teema: `${r ? `Lisa ${r.nr}` : "Üürileping"} ootab teie allkirja · ${d.id}`,
    tekst: `${tere}\n\n${r ? `Üürilepingu ${d.id} Lisa ${r.nr}` : `Üürileping ${d.id} (${sp.nimi}, ${obj.nimi})`} ootab teie allkirja alates ${saatsin}.${P.yhine ? ` ${P.nimi} esindavad ühiselt ${P.isikud.map(x => x.nimi).join(" ja ")}${teised.length ? ` — ${teised.join(" ja ")} on juba allkirjastanud` : ""}.` : ""}\n\nAllkirjastamine käib lingi kaudu Dokobiti aknas (Smart-ID, Mobiil-ID või ID-kaart).\n\n${p4Allkiri()}` };
}
function p6MeenutaJuht(kind, doc, ring) {
  const v = p6Vaikus(kind, doc, ring); if (!v) return "";
  const T = p6MeenutaMall(v), nr = ring ? ring.nr : "null";
  const meta = v.kind === "allk" ? `Kutse ${p4Aeg(v.kiri.aeg)}` : `Saadetud ${p4Aeg(v.kiri.aeg)}${v.kiri.avatud ? ` · avas lingi ${p4Aeg(v.kiri.avatud)}` : " · linki pole avanud"}`;
  return `<div class="guide me reveal p6-mm-g">
      <span class="g-top"><span class="g-kes">${kordMark("minu", "Sinu kord")}</span></span>
      <span class="g-tx"><b>${escH(v.saaja.nimi)}</b> pole ${p4P(v.paevi)} ${v.kind === "allk" ? "allkirjastanud" : "vastanud"} — saada meeldetuletus?</span>
      <span class="g-meta">${escH(meta)}</span>
      <div class="p6-mm">
        <div class="p6-mm-h"><span>Mustand · ${escH(v.saaja.epost || v.saaja.nimi)}</span><button type="button" class="steplink" id="p6-mm-muuda" aria-expanded="false" onclick="p6MmMuuda()">Muuda</button></div>
        <div class="p6-mm-v"><b>${escH(T.teema)}</b><p>${escH(T.tekst)}</p></div>
        <div class="p6-mm-e" hidden>
          <label class="p4-pv-l" for="p6-mm-teema">Teema</label><input id="p6-mm-teema" class="ce-in" value="${escH(T.teema)}" autocomplete="off">
          <label class="p4-pv-l" for="p6-mm-tekst">Kiri</label><textarea id="p6-mm-tekst" class="ce-in" rows="8">${escH(T.tekst)}</textarea>
        </div>
      </div>
      <button class="btn btn-primary btn-sm" onclick="p6Meenuta('${kind}', '${doc.id}', ${nr})">Saada meeldetuletus<span class="bic">${I.arrow}</span></button>
      <span class="p4-vaiksed"><button type="button" class="steplink" onclick="p6Hiljem('${kind}', '${doc.id}', ${nr})">Mitte praegu</button></span>
    </div>`;
}
window.p6MmMuuda = () => {
  const e = document.querySelector(".p6-mm-e"), v = document.querySelector(".p6-mm-v"), b = document.getElementById("p6-mm-muuda"); if (!e || !v) return;
  const lahti = e.hidden; e.hidden = !lahti; v.hidden = lahti; if (b) { b.setAttribute("aria-expanded", String(lahti)); b.textContent = lahti ? "Eelvaade" : "Muuda"; }
  if (lahti) { const t = document.getElementById("p6-mm-tekst"); if (t) t.focus({ preventScroll: true }); }
};
const p6Doc = (kind, id) => kind === "o" ? DB.offerById(id) : lepLive(DB.leaseById(id));   /* v805: „Mitte praegu” ei kao hetktõmmisesse */
window.p6Meenuta = (kind, id, nr) => {
  const doc = p6Doc(kind, id); if (!doc) return;
  const ring = nr != null ? (doc.muudatused || []).find(m => m.nr === nr) : null, v = p6Vaikus(kind, doc, ring); if (!v) return;
  const T = p6MeenutaMall(v), te = document.getElementById("p6-mm-teema"), tk = document.getElementById("p6-mm-tekst");
  const k = p4Kiri(doc, { liik: "meeldetuletus", lisa: ring ? ring.nr : undefined, isik: v.isik ? v.isik.id : undefined,
    teema: (te && te.value.trim()) || T.teema, tekst: (tk && tk.value.trim()) || T.tekst, saaja: v.saaja });
  if (kind === "allk" && v.isik) { const d = ring || doc; (d.allkKutsed = d.allkKutsed || {})[v.isik.id] = k.aeg; }
  DB.save(); toast(k.olek === "porkus" ? `Meeldetuletus ei jõudnud kohale — ${k.pohjus}` : `Meeldetuletus saadetud · ${v.saaja.nimi} · kohale toimetatud`); router();
};
window.p6Hiljem = (kind, id, nr) => {
  const doc = p6Doc(kind, id); if (!doc) return;
  const ring = nr != null ? (doc.muudatused || []).find(m => m.nr === nr) : null;
  (ring || doc).meenutaEdasi = fmtEE(new Date(DEMO_TODAY.getTime() + 3 * 864e5));
  AUDIT.unshift({ aeg: NOW_EE(), autor: "Tarmo Sepp", tegevus: `${doc.id}${ring ? ` Lisa ${ring.nr}` : ""}: meeldetuletus lükati edasi kuni ${(ring || doc).meenutaEdasi}.` });   /* v793 */
  DB.save(); toast("Selge — küsin uuesti 3 päeva pärast"); router();
};

/* ---------- Avaleht: vaikus · pikendus · rakendunud indekseerimine (üks allikas: sama loogika mis juhtkaardil) ---------- */
function p6AvRead(Q) {   /* v643: vaikus, pikendus ja allkirjad tulevad p7Samm-ist (üks otsus) — siin ainult rakendunud indekseerimine */
  LEASES.forEach(l => {
    const cl = DB.clientById(l.clientId); if (!cl || lepArh(l) || !lepSigned(l)) return;
    const ia = ((l.indeks || {}).ajalugu || []).slice(-1)[0];
    if (ia) { const p = p6Moodas(ia.kp); if (p <= p6Teav("indeks", 30))
      Q.push({ key: "idxv-" + l.id, tone: "green", date: parseEE(ia.kp), t: `${avLyh(cl.nimi)} üür indekseeriti`, s: `${lepPindTxt(l)} · ${eur(ia.kuusVana)} → ${eur(ia.kuusUus)} € kuus, teade saadeti`,
        fm: `Üürileping ${l.id} · ${ia.kp} · ${ia.silt}`, aeg: avMillal(-p), verb: "Vaata", href: "#/leping/" + l.id, ic: I.trend }); }
  });
}

/* ---------- seeme (esmakäivitus, Taevavärava): Maatransi lõppev leping — ühine esindusõigus, 2 rakendunud indekseerimist,
   pikenduse mustand valmib automaatikaga. Algus = selle kuu 1. kaks aastat tagasi → lõpp jääb alati 90 päeva aknasse. ---------- */
function p6Seed() {
  if (DB.COMPANY_ID !== "taeva" || LEASES.some(l => l.p6Seeme)) return;
  const cl = DB.clientById("c-baltic"), sp = DB.spaceById("p8"); if (!cl || !sp || sp.staatus !== "Vaba") return;
  const algusD = new Date(DEMO_TODAY.getFullYear() - 2, DEMO_TODAY.getMonth(), 1), aISO = fmtISO(algusD);
  let kuud = 27; if (Math.round((addKuudISO(aISO, kuud) - DEMO_TODAY) / 864e5) > 89) kuud = 26;
  const P0 = (cl.allkirjastajad || [])[0] || { nimi: cl.kontakt, epost: cl.epost };
  const l = createLease({ cl, sp, tehing: { algus: aISO, kuud, hind: sp.hind, tagatisKuud: seVaike().tagatisKuud, parkimine: sp.parkimine || 0, otstarve: null, erisused: null },
    pakkumus: null, kontakt: { nimi: P0.nimi, epost: P0.epost || cl.epost, tel: cl.tel } });
  l.id = `LEP-${algusD.getFullYear()}-001`; l.p6Seeme = true; l.punktid = buildPunktid(l, cl, sp);
  const saadetud = new Date(algusD.getTime() - 24 * 864e5), allk = fmtEE(new Date(algusD.getTime() - 12 * 864e5));
  lepV1Snap(l); l.v1.aeg = `${fmtEE(saadetud)} 11:20`; l.saadetud = l.v1.aeg;
  const yl = p6Pool(l, "yl"), yn = p6Pool(l, "yn");
  l.allk = [{ k: "yl", isikId: yl.isikud[0].id, isik: yl.isikud[0].nimi, roll: yl.isikud[0].roll, pool: yl.nimi, meetod: "Smart-ID", aeg: `${allk} 10:42` }]
    .concat(yn.isikud.map((i, n) => ({ k: "yn", isikId: i.id, isik: i.nimi, roll: i.roll, pool: yn.nimi, meetod: n ? "Mobiil-ID" : "Smart-ID", aeg: `${allk} ${n ? "16:08" : "14:05"}` })));
  p6SlotSync(l, l);
  l.staatus = "Kehtiv"; l.allkirjastatud = allk; l.versioon = null;
  sp.staatus = "Üüritud"; sp.tenant = cl.nimi;
  p6Audit({ aeg: `${fmtEE(saadetud)} 11:20`, autor: P6_OP, tegevus: `${l.id} mustand saadetud üürnikule.` });
  p6Audit({ aeg: `${allk} ${yn.isikud.length > 1 ? "16:08" : "14:05"}`, autor: yn.isikud[yn.isikud.length - 1].nimi,
    tegevus: `${l.id} allkirjastatud — ${l.allk.length} allkirja (${yl.nimi}; ${yn.nimi}${yn.yhine ? ", ühine esindusõigus" : ""}). Leping kehtib; konteiner ${l.id}.asice.` });
  DB.save();
}
