      const kp = x.klauslid.punktid, t = p8IndeksTxt({ punktid: kp.filter(p => /^(PT|ÜT)$/.test(p.osa)), lisad: [{ punktid: kp.filter(p => /^L\d/.test(p.osa)) }] });
