  if ((m = h.match(/^#\/pakkumus(?:-doc)?\/(.+)/))) { const o = DB.offerById(m[1]); if (o) { const c = DB.clientById(o.clientId); return { kind: "offer", id: o.id, lbl: `${o.id} · ${c ? c.nimi : ""}`, href: h }; } }
  if ((m = h.match(/^#\/osapool\/(.+)/))) { const p = osapoolById(decodeURIComponent(m[1])); if (p) return { kind: "osapool", id: p.id, lbl: p.nimi, href: h }; }
