    if (!l) return { steps: S, ans: { lause: `${escH(dok.id)} on tähtajatu — lõppkuupäeva lepingus ei ole.`, viited: [aiViide(dok.id, /tähtajatu|tähtaeg|kehtivus/i)].filter(Boolean), lingid: r.href ? [{ href: r.href, t: "Ava leping" }] : [] } };
    const d = aiPaevi(l), kd = KEY_DATES.filter(k => String(k.objekt).startsWith(dok.id + " ") && kpD(k.kuupaev) >= DEMO_TODAY).sort((a, b) => kpD(a.kuupaev) - kpD(b.kuupaev));
