  S.push({ t: "Loen kehtivaid lepinguid", tool: "portfell.loe", det: `${aiN(A.R.length, "leping", "lepingut")} üüriga · ajaaken ${w.lbl}` });
  const rida = (x) => ({ t: escH(x.e.r.klient), s: `${escH(aiLyh(x.e.r))} · ${escH(x.e.r.id)}`, m: fmtEE(x.e.l), v: aiEu(x.v), href: x.e.r.href, viide: aiViideKp(x.e.r.id, x.e.l) });
  if (!L.length) { const nx = A.R.filter(e => e.l && e.l > DEMO_TODAY).sort((a, b) => a.l - b.l)[0];
    return { steps: S, ans: { lause: `${aiSuur(w.lbl)} ükski leping ei lõpe.${nx ? ` Järgmine lõpeb <b>${fmtEE(nx.l)}</b>: ${escH(nx.r.klient)}.` : ""}`, read: nx ? [rida({ e: nx, v: nx.kuus })] : [], lingid: [{ href: "#/kalender", t: "Ava kalender" }] } }; }
  const sum = L.reduce((s, x) => s + x.v, 0);
