  const KD = KEY_DATES.filter(k => /Indekseer/i.test(k.tyyp)).map(k => ({ k, id: String(k.objekt).split(" · ")[0], d: kpD(k.kuupaev) })).filter(x => x.d >= DEMO_TODAY).sort((a, b) => a.d - b.d);
  const summa = (id) => { const e = A.R.find(x => x.r.id === id); return e ? { vana: e.kuus, uus: e.kuus * (1 + e.pct), silt: e.silt || p6PctM(e.pct) } : null; };   /* v642: üks arvutus */
