  const rida = (x) => { const s = summa(x.id), e = A.R.find(y => y.r.id === x.id); return { t: escH(e ? e.r.klient : String(x.k.objekt).split(" · ")[1] || x.id), s: `${escH(e ? aiLyh(e.r) : "")}${e ? " · " : ""}${escH(x.id)}`, m: fmtEE(x.d), v: s ? `+${aiEu(s.uus - s.vana)}` : pctTx(s), href: e ? e.r.href : null, viide: aiViide(x.id, /indeks/i) }; };
  if (!L.length) return { steps: S, ans: { lause: w ? `${aiSuur(w.lbl)} ükski leping ei indekseeru.` : "Ees ei ole ühtegi indekseerimist.", read: KD[0] ? [rida(KD[0])] : [] } };
  const kasv = L.reduce((a, x) => { const s = summa(x.id); return a + (s ? s.uus - s.vana : 0); }, 0);
