/* vabas vormis küsimus lepingu SISU kohta → klauslikiht: üks lause (kehtiv sõnastus) + kus kehtib + punktiviited */
function aiKlausel(cmd, q, ctx) {
  /* üldsõnad välja („mis on … kohta kirjas", „selles lepingus") — otsime sisusõnu; vaste peab katma vähemalt poole neist ja üks peab olema pikk */
  const puhas = cmd.replace(/\b(mis|mida|on|kohta|kirjas|kirjutatud|öeldud|sätestatud|lepingus|lepingu|leping|lepingut|lepingud|lepingule|selle|see|seda|sellel|selles|antud|kas|siin|mind|meil)\b/gi, " ");
  const r = klOtsi(puhas, 80);
  let hits = r.hits.filter(h => { const txt = `${klKehtiv(h.p) || h.p.tekst} ${h.p.pealkiri}`.toLowerCase(), m = r.toks.filter(t => txt.includes(t));
    return m.length >= Math.ceil(r.toks.length / 2) && m.some(t => t.length >= 4); });
  const dok = aiDok(q, ctx, true), dokId = dok && dok.id && klauslidOf(dok.id) ? dok.id : null;
  if (dokId) hits = hits.filter(h => h.id === dokId);
  const S = [{ t: "Analüüsin küsimust", tool: null, det: `Otsisõnad: ${r.toks.join(", ") || "—"}` },
    { t: "Otsin lepingute punktidest", tool: "klauslid.otsi", det: `${r.total} punkti${dokId ? ` · ainult ${dokId}` : ""} · ${hits.length} vastet` }];
  if (!hits.length) return aiEiLeia(ctx, S);
  const G = new Map(); hits.forEach(h => { const k = aiNorm(klKehtiv(h.p) || h.p.tekst).slice(0, 150); if (!G.has(k)) G.set(k, []); G.get(k).push(h); });
  const grupid = [...G.values()], top = grupid[0], p = top[0].p, kehtetu = p.muudetud && p.muudetud.viis === "kehtetu";
  S.push({ t: "Kontrollin lisade muudatusi", tool: "lisad.kehtiv", det: p.muudetud ? `${p.muudetud.lisa} muudab punkti — tsiteerin kehtivat sõnastust` : "Vastust lisad ei muuda" });
  const doks = [...new Map(top.map(h => [h.id, h])).values()];
  const rida = (h) => { const x = DB.impById(h.id); return { t: escH(x ? x.pool : h.id), s: escH(h.id), m: `${klOsaLbl(h.p)}${h.p.nr}${h.p.lk ? ` · lk ${h.p.lk}` : ""}`, v: "", vid: aiViideP(h.id, h.p) }; };
  return { steps: S, ans: {
    lause: kehtetu ? `Punkt ${klOsaLbl(p)}${p.nr} on ${escH(p.muudetud.lisa)}-ga kehtetuks tunnistatud.` : `„${escH(klTsitaat(p, r.toks, 260))}"`,
    viited: doks.slice(0, 3).map(h => aiViideP(h.id, h.p)),
    pea: dokId ? (grupid.length > 1 ? "Seotud punktid samas lepingus" : null) : doks.length > 1 ? `Sama sõnastus ${aiN(doks.length, "lepingus", "lepingus")}` : null,
    read: dokId ? grupid.slice(1, 4).map(g => { const h = g[0]; return { t: escH(`${klOsaLbl(h.p)}${h.p.nr} · ${String(h.p.pealkiri || "").toLowerCase()}`), s: escH(klTsitaat(h.p, r.toks, 110)), v: "", vid: aiViideP(h.id, h.p) }; })
      : doks.length > 1 ? doks.slice(0, 6).map(rida) : [],
    lingid: [] } };
}
