View.agent.init = () => {
  document.body.classList.add("ai-on");
  const root = document.querySelector(".ai-leht"); if (!root) return;
  const f = document.getElementById("agent-follow");
  if (f) f.addEventListener("keydown", e => { if (e.key === "Enter" && !e.isComposing) { e.preventDefault(); if (f.value.trim()) aiKysi(f.value); } });
  root.addEventListener("click", (e) => {
    const t = e.target.closest && e.target.closest("[data-kin],[data-del],[data-loim],.ai-viide,[data-q],.ai-rida[data-href],.ai-rida[data-vid]"); if (!t) return;
    if (t.dataset.kin != null) { aiOtsus(+t.dataset.i, +t.dataset.kin); return; }
    if (t.dataset.del) { e.stopPropagation(); aiLoimKustuta(t.dataset.del); return; }
    if (t.dataset.loim) { aiLoimAva(t.dataset.loim); return; }
    if (t.dataset.vid && (t.classList.contains("ai-viide") || t.classList.contains("ai-rida"))) { e.stopPropagation(); aiViideAva(t.dataset.vid, t.dataset.vkey); return; }
    if (t.dataset.q) { aiKysi(t.dataset.q); return; }
    if (t.dataset.href) location.hash = t.dataset.href;
  });
  root.addEventListener("keydown", (e) => { if (e.key === "Enter" && e.target.classList && e.target.classList.contains("ai-rida")) e.target.click(); });
  const main = root.querySelector(".ail-main"), veerg = document.getElementById("ail-veerg");
  if (main && veerg) main.addEventListener("click", (e) => { if (veerg.classList.contains("lahti") && !e.target.closest(".ail-menyy")) veerg.classList.remove("lahti"); });
  if (AGENT.pending) { const c = AGENT.pending; AGENT.pending = null; setTimeout(() => aiKysi(c), 60); }
  else { if (f) f.focus(); if (AI_LOIM && AI_LOIM.msgs.length) aiKeri(); }
};
