    const pp = o ? kl.punktid.filter(p => p.osa === o) : (l.punktid || []).map((p, i) => ({ nr: String(i + 1), osa: "L" + nr, jagu: "Lisa " + nr, pealkiri: p.pealkiri, tekst: p.tekst, muudab: p.muudab, lk: 0 }));
    const M = (x.muutused || []).filter(m => m.lisa === nr);
    const muut = M.length ? `<table class="sh-tbl imp-mt"><tbody>${M.map(m => `<tr><td>${escH(m.silt)}</td><td><s>${m.enne || "—"}</s></td><td>→</td><td><b>${m.parast}</b></td></tr>`).join("")}</tbody></table>` : "";
