  if (!arh) T.push(rida("Registreeri uus lisa", "väljaspool platvormi", `href="#/import"`));
  P.forEach(sp => T.push(rida(`Ava ${escH(sp.nimi)}`, "pinna leht", `href="#/pind/${sp.id}"`)));
