/* klauslite loend vaates: osa → jagu → punktid; Lisa 3 muudetud punktil kehtiv tekst ees, algne all */
/* v576 (audit 6): poolte punkt originaalist on „Nimi: … Aadress: … E-post: …" üks rida — kuva siltide kaupa ja
   ütle selgelt, et need on SÕLMIMISE AEGSED andmed (originaali ei muudeta; praegused andmed on profiilis/kliendikaardil) */
const KL_POOLE_SILDID = ["Nimi", "Registrikood", "Aadress", "KM-number", "E-post", "Telefon", "Pank", "Kontonumber"];
function klPooledHTML(id, p) {
  const t = String(p.tekst || "");
  if (p.osa !== "PT" || !/\bNimi:/.test(t) || !/Registrikood:/.test(t)) return null;
  const roll = t.split(/\s*Nimi:/)[0].trim();
  const re = new RegExp("(" + KL_POOLE_SILDID.join("|") + "):", "g"), osad = []; let m, eel = null;
  while ((m = re.exec(t))) { if (eel) eel.v = t.slice(eel.i, m.index).trim(); eel = { k: m[1], i: m.index + m[0].length }; osad.push(eel); }
  if (eel) eel.v = t.slice(eel.i).trim();
  const x = IMPORDITUD.find(y => y.id === id);
  return `<div class="kl-pool"><b>${escH(roll)}</b>${osad.filter(o => o.v).map(o => `<div class="kl-kv"><span>${escH(o.k)}</span><span>${escH(o.v)}</span></div>`).join("")}
    <div class="kl-note">Andmed lepingu sõlmimise ajal${x && x.solmitud ? ` (${escH(x.solmitud)})` : ""} originaalist — praegused andmed on ${roll === "Üürileandja" ? "ettevõtte profiilis" : "kliendikaardil"}.</div></div>`;
}
View.imporditud.init = () => {
  const q = document.getElementById("kl-q"), dok = document.getElementById("imp-dok"), n = document.getElementById("imp-otsi-n"); if (!dok) return;
  const vilgu = (el) => { if (!el) return; el.scrollIntoView({ behavior: "smooth", block: el.classList.contains("imp-leht") ? "start" : "center" }); el.classList.add("hl"); setTimeout(() => el.classList.remove("hl"), 2600); };
  if (q) q.addEventListener("input", () => {
    const v = q.value.trim().toLowerCase(); let k = 0;
    dok.querySelectorAll(".imp-p").forEach(r => { r.hidden = !!v && !r.dataset.txt.includes(v); if (v && !r.hidden) k++; });
    dok.querySelectorAll(".imp-jagu").forEach(j => { j.hidden = !j.querySelector(".imp-p:not([hidden])"); });
    dok.querySelectorAll(".imp-leht[data-osa]").forEach(o => { o.hidden = !o.querySelector(".imp-p:not([hidden])"); });
    if (n) n.textContent = v ? `${k} ${k === 1 ? "vaste" : "vastet"}` : "";
  });
  document.querySelectorAll(".imp-eri-r, .imp-tk-r[data-goto], .imp-src[data-goto]").forEach(b => b.onclick = () => { const g = b.dataset.goto;
    if (q && q.value) { q.value = ""; q.dispatchEvent(new Event("input")); }
    vilgu(g.startsWith("k:") ? dok.querySelector(`.imp-p[data-key="${g.slice(2)}"]`) : document.getElementById(g.slice(3))); });
  if (IMP_FOCUS) { const row = dok.querySelector(`.imp-p[data-key="${IMP_FOCUS}"]`); IMP_FOCUS = null; if (row) setTimeout(() => vilgu(row), 120); }
};

/* ---------- Lepingu detail ------------------------------------------------ */
let LEP_FOCUS_ID = null;
/* muudatusrežiim (Kehtiv leping): dokumendi asemel klõpsatav punktivaade —
   klient kommenteerib, operaator lisab muudatusi ringi (→ Lisa N) */
let LEP_MUUDATUS_MODE = false;
window.lepMuudatus = (on) => { LEP_MUUDATUS_MODE = on && !lepArh(CURRENT_LEASE) && !(CURRENT_LEASE && CURRENT_LEASE.sulgemine); router(); };

/* ---------- juhitud vool: süsteem juhib, kasutaja ei otsi ------------------ */
/* järgmine punkt, mis vajab PRAEGUSE rolli tegevust — kommentaaride tekkejärjekorras.
   Operaatoril: punkt, kus üürniku sõna oli viimane (otsusta või vasta).
   Üürnikul: kinnitust ootav ettepanek VÕI arutelu, kus üürileandja küsis viimasena. */
function nextOpenPunkt(l) {
  const cs = l.arutelud || [];
  const c = isClient()
    ? cs.find(x => x.staatus === "Ootab kinnitust" || (x.staatus === "Ootel" && !aruOotabOp(x)))
    : cs.find(aruOotabOp);
  if (c) return c.punktId;
  if (!isClient()) { const k = (l.punktid || []).find(p => p.kontrolli); if (k) return k.id; }
  return null;
}
