  const minuKaik = lahti.some(c => isClient() ? (c.staatus === "Ootab kinnitust" || (c.staatus === "Ootel" && !aruOotabOp(c))) : aruOotabOp(c));
  const kell = (a) => a ? String(a).replace(/^(\S+) (\d\d:\d\d)$/, "$1 kell $2") : "";
