  const kokku = nKom ? `Arutelu ja ajalugu · ${nKom} ${nKom === 1 ? "kommentaar" : "kommentaari"}` : hv.length ? `Ajalugu · ${hv.length} ${hv.length === 1 ? "muudatus" : "muudatust"}` : "";
