      <label class="po-preview-f"><span class="muted">Klient</span><select id="persona-pick">${demoable.map(x => `<option value="${x.id}" ${x.id === c.id ? "selected" : ""}>${escH(x.nimi)}</option>`).join("")}</select></label>
