/* ==========================================================================
   v653 (kasutaja): PINNA LEHT #/pind/<id> — pinna elu ühes kohas (osapoole lehe muster):
   päis (olek, tulev muutus, arvud) · juhtkaart · Praegu (leping/pakkumus, kaardimudel) · Tähtajad ja muudatused ·
   Arhiiv (varasemad lepingud, lõppenud pakkumised) · külgveerus Toimingud (oleku järgi) ja pinna andmed.
   ========================================================================== */
/* lepingu seos pinnaga: "on" (kehtiv/jõustunud, ka tulevikus lisanduv) · "ring" (Lisa N koostamisel/allkirjastamisel lisab selle pinna)
   · "endine" (pind oli lepingus, eemaldati) · null */
function lepPindSeos(l, sid) {
  if (lepOnPind(l, sid)) return "on";
  const r = aktiivneRing(l);
  if (r && (r.pinnad || []).some(x => x.spaceId === sid && x.tyyp === "lisa")) return "ring";
  return lepPohiPindIds(l).includes(sid) || lepPindMuutused(l).some(x => x.spaceId === sid) ? "endine" : null;
}
function pinnaDokRead(s) {
  const read = [];
  pfLepinguRows().forEach(r => {
    const seos = r.kind === "lease" ? lepPindSeos(r.l, s.id) : null;
    if (seos) read.push({ ...r, arh: r.arh || seos === "endine" });
    else if ((r.kind === "imp" || r.kind === "imp-eel") && r.x && r.x.liik === "Üürileping"
      && (r.x.pindIds || []).includes(s.id)) read.push(r); });
  pfPakkumisedRows().forEach(r => { if ((r.o.spaceIds || []).includes(s.id)) read.push({ ...r, arh: OFFER_LOPP.includes(r.o.staatus) }); });
  return { akt: read.filter(r => !r.arh), arh: read.filter(r => r.arh) };
}
/* tähtajad: pinna dokumentide võtmekuupäevad + selle pinna üleandmised/tagastamised + koostamisel ringi pinnamuudatused */
function pinnaTahtajad(s, docs) {
  const ids = docs.map(r => r.id), onPinna = (k) => /^Pinna /.test(k.tyyp) ? String(k.info || "").startsWith(s.nimi + " ·") : true;
  const L = KEY_DATES.filter(k => ids.some(id => String(k.objekt).startsWith(id + " ")) && onPinna(k));
  LEASES.filter(l => !lepArh(l)).forEach(l => { const r = aktiivneRing(l), cl = DB.clientById(l.clientId) || {};
    ((r && r.pinnad) || []).filter(x => x.spaceId === s.id).forEach(x => L.push({ kuupaev: x.kpv, tyyp: x.tyyp === "lisa" ? "Pinna üleandmine" : "Pinna tagastamine",
      margis: "amber", objekt: `${l.id} · ${cl.nimi || ""}`, info: `${s.nimi} · Lisa ${r.nr} · ${r.staatus.toLowerCase()}, allkirjastamata` })); });
  /* kehtiva dokumendi lõpp / pakkumise kehtivus, kui kalendris seda eraldi kirjet pole (sama allikas mis kaardi „järgmine") */
  docs.filter(r => !r.arh).forEach(r => {
    const tyyp = r.o ? "Pakkumise kehtivus" : r.l ? "Lepingu lõpp" : null, kp = r.o ? r.o.kehtivKuni : r.lopp;
    if (!tyyp || !/^\d\d\.\d\d\.\d{4}$/.test(String(kp)) || L.some(k => k.tyyp === tyyp && String(k.objekt).startsWith(r.id + " "))) return;
    L.push({ kuupaev: fmtISO(new Date(eeMs(kp))), tyyp, margis: r.o ? "amber" : "accent", objekt: `${r.id} · ${r.klient}`, info: r.o ? "Pakkumine aegub" : "Tähtajaline leping lõpeb" }); });
  return L.sort((a, b) => String(a.kuupaev).localeCompare(String(b.kuupaev)));
}
View.pind = (id) => {
  const s = DB.spaceById(id); if (!s) return notFound("Pinda ei leitud");
  const obj = objektOf(s), tanaIso = fmtISO(DEMO_TODAY), aj = pindAjakava(s.id);
  const { akt, arh } = pinnaDokRead(s), mud = pfJarjesta(akt.map(pfMudel)), ar = arhiivLoend(arh, "", { seisud: false });
  PF_ROWS = mud.map(x => x.r);
  const lep = LEASES.find(l => !lepArh(l) && lepPindSeos(l, s.id) === "on") || LEASES.find(l => !lepArh(l) && lepPindSeos(l, s.id) === "ring"),
    ringX = lep && lepPindSeos(lep, s.id) === "ring" ? aktiivneRing(lep).pinnad.find(x => x.spaceId === s.id) : null, pak = !lep && OFFERS.find(o => (o.spaceIds || []).includes(s.id) && !OFFER_LOPP.includes(o.staatus));
  const imp = !lep && akt.find(r => r.x), kuusP = !ringX && pindKuusNyyd(s), hind = ringX ? ringX.hind : kuusP ? kuusP / s.yyripind : lep ? lepHind(lep, s) : s.hind;   /* v805: sama tänane üür kui mujal */
  const tt = pinnaTahtajad(s, [...akt, ...arh]), tulevad = tt.filter(k => k.kuupaev >= tanaIso).length;
  const ema = s.emaId ? DB.spaceById(s.emaId) : null, yksused = s.jagatud ? SPACES.filter(c => c.emaId === s.id) : [];
  /* juhtkaart: dokumendi järgmine samm › vaba pind = tee pakkumine */
  const r0 = akt.map(r => ({ r, sm: pfSamm(r) })).find(x => x.sm && x.sm.kord === "minu") || akt.map(r => ({ r, sm: pfSamm(r) })).find(x => x.sm);
  const g = s.jagatud ? { kord: "ok", tx: `Pind on jagatud üksusteks (${yksused.map(c => c.nimi).join(" + ")}) — dokumendid on üksuste lehtedel.` }
    : r0 ? { ...r0.sm, tx: `${r0.sm.tx} · ${r0.r.id}`, href: r0.sm.href || r0.r.href, nupp: r0.sm.kord === "minu" ? r0.sm.tx.split(" · ")[0] : "Ava" }
    : s.staatus === "Vaba" ? { kord: "minu", tx: "Pind on vaba — tee pakkumine või lisa pind mõne üürniku kehtivale lepingule.", nupp: "Loo pakkumine", act: `pindUusPak('${s.id}')` } : null;
  /* toimingud oleku järgi (paremal) */
  const rida = (tx, meta, attr) => `<${attr.startsWith("href") ? "a" : "button type=\"button\""} class="act-row" ${attr}><span>${tx}</span>${meta ? `<span class="mono" style="font-size:10.5px;color:var(--faint)">${meta}</span>` : ""}<span class="chev">${I.arrow}</span></${attr.startsWith("href") ? "a" : "button"}>`;
  const T = [];
  if (s.jagatud) yksused.forEach(c => T.push(rida(`Ava ${escH(c.nimi)}`, `${eur(c.yyripind, 1)} m²`, `href="#/pind/${c.id}"`)));
  else if (lep) {
    T.push(rida("Ava leping", ringX ? `${lep.id} · Lisa ${aktiivneRing(lep).nr}` : lep.id, `href="#/leping/${lep.id}"`));
    if (lepSigned(lep) && !lep.sulgemine && !ringX) {
      T.push(rida("Algata muudatus", `→ Lisa ${(aktiivneRing(lep) || { nr: nextLisaNr(lep) }).nr}`, `onclick="pindMuudatus('${lep.id}')"`));
      if (lepPinnad(lep).length > 1) T.push(rida("Eemalda pind lepingust", "Lisa N", `onclick="openPindMuut('${lep.id}','eemalda','${s.id}')"`));
      T.push(rida("Lepingu lõpetamine", "", `href="#/leping/${lep.id}"`));
    }
  } else if (pak) T.push(rida("Ava pakkumine", pak.id, `href="#/pakkumus/${pak.id}"`));
  else if (imp) T.push(rida("Ava imporditud leping", imp.x.id, `href="#/imp/${imp.x.id}"`));
  else if (s.staatus === "Vaba") {
    T.push(rida("Loo pakkumine", "", `onclick="pindUusPak('${s.id}')"`));
    LEASES.filter(l => lepSigned(l) && !lepArh(l) && !l.sulgemine && (objektOf(DB.spaceById(l.spaceId)) || {}).id === obj.id).slice(0, 4)
      .forEach(l => T.push(rida(`Lisa lepingule ${l.id}`, escH((DB.clientById(l.clientId) || {}).nimi || ""), `onclick="openPindMuut('${l.id}','lisa','${s.id}')"`)));
    if (!jagaKeeld(s)) T.push(rida("Jaga üksusteks", "harv erijuht", `onclick="openJaga('${s.id}')"`));
    if (!pindKustutaKeeld(s)) T.push(`<button type="button" class="act-row" onclick="pindKustuta('${s.id}')"><span style="color:var(--red)">Kustuta pind</span><span class="chev">${I.arrow}</span></button>`);   /* v794 */
  }
  const plaan = s.plaanFail || (obj.failid || {}).pinnaplaan;
  const kohad = lep && lepPinnad(lep).length === 1 ? lepParkKohad(lep).slice().sort((a, b) => a - b) : [];
  return `
  <div class="view op pinna">
    <a class="btn btn-ghost btn-sm reveal" href="#/objekt/${obj.id}" style="margin-bottom:18px">${I.back} ${escH(obj.nimi)}</a>
    <div class="op-pea reveal">
      <div class="op-pea-l">
        <div class="overline">Pind · ${escH(obj.nimi)}</div>
        <h1 class="page-h1">${escH(s.nimi)}</h1>
        <div class="op-meta"><span>${escH(s.tyyp || "")}</span>${ema ? `<a class="steplink" href="#/pind/${ema.id}">osa pinnast ${escH(ema.nimi)} →</a>` : ""}${pill(s.staatus)}</div>
        ${aj ? `<a class="sp-ajakava" href="#/leping/${aj.lid}">${I.cal}<span>${escH(aj.tx)} · Lisa ${aj.nr}${aj.ootel ? " · allkirjastamata" : ""}</span></a>` : ""}
      </div>
      <div class="op-arvud">
        <div><b>${eur(s.yyripind, 1)} m²</b><span>üüripind</span></div>
        <div><b>${eur(hind)} €</b><span>${ringX ? "€/m² Lisa N-s" : lep || imp ? "€/m² lepingus" : "€/m² hinnakiri"}</span></div>
        <div><b>${eur(s.yyripind * hind, 0)} €</b><span>${kuusP || ringX || lep ? "üür kuus" : "üür kuus hinnakirja järgi"}</span></div>
      </div>
    </div>
    ${g ? `<div class="guide op-juht ${g.kord === "minu" ? "me" : g.kord === "teine" ? "wait" : "ok"} reveal">
      <span class="g-top"><span class="g-kes">${kordMark(g.kord, g.kord === "minu" ? "Sinu kord" : g.kord === "teine" ? "Teise poole kord" : "Korras")}</span></span>
      <span class="g-tx">${escH(g.kord === "ok" ? String(g.tx).replace(/^Korras\s·\sjärgmine\s/, "Järgmine tähtaeg ").replace(/^Korras$/, "Midagi ei oota — tähtajad on kalendris.") : g.tx)}</span>${g.act ? `<button type="button" class="btn btn-primary btn-sm" onclick="${g.act}">${escH(g.nupp)}<span class="bic">${I.arrow}</span></button>` : g.href ? `<a class="btn ${g.kord === "minu" ? "btn-primary" : "btn-ghost"} btn-sm" href="${g.href}">${escH(g.nupp || "Ava")}<span class="bic">${I.arrow}</span></a>` : ""}</div>` : ""}
    <div class="op-grid">
      <div class="op-pohi">
        <section class="reveal">
          <div class="sec-h"><h2>Praegu</h2><span class="meta">${arvMark(akt.length) || ""}</span></div>
          <div class="op-docs">${pfLoendHTML(mud, "cards", s.jagatud ? "Jagatud pinnal dokumente pole — vaata üksusi." : "Pinnal pole praegu lepingut ega pakkumist.")}</div>
        </section>
        <section class="reveal">
          <div class="sec-h"><h2>Tähtajad ja muudatused</h2><span class="meta">${tulevad ? arvMark(tulevad) : ""}</span><a class="steplink op-sec-link" href="#/kalender">Kalender →</a></div>
          <div class="card op-tt">${tt.length ? tt.map(k => opTahtaegHTML(k, tanaIso)).join("") : `<div class="op-tyhi">Tähtaegu ega pinnamuudatusi pole.</div>`}</div>
        </section>
        ${arh.length ? `<details class="card reveal op-arh"><summary><b>Arhiiv</b><span>${arh.length} ${arh.length === 1 ? "dokument" : "dokumenti"} · varasemad lepingud ja pakkumised</span>${I.chevD}</summary>${ar.html.replace(/data-pfrow="(\d+)"/g, (x, i) => `data-pfrow="${+i + mud.length}"`)}</details>` : ""}
      </div>
      <aside class="op-kyljel">
        <div class="sec-h reveal"><h2>Toimingud</h2></div>
        <section class="card op-kaart reveal pinna-teg">${T.length ? T.join("") : `<div class="op-tyhi">Toiminguid pole — pind on ${escH(String(s.staatus).toLowerCase())}.</div>`}</section>
        <section class="card op-kaart reveal">
          <div class="op-kaart-pea"><span class="overline">Pind</span><span class="pinna-lingid">${plaan ? `<button type="button" class="steplink" onclick="openPdf('${escH(plaan)}','Pinnaplaan · ${escH(s.nimi)}')">Pinnaplaan</button>` : ""}${s.jagatud || isClient() ? "" : `<button type="button" class="steplink" onclick="pindMuuda('${s.id}')">Muuda andmeid →</button>`}</span></div>
          ${(s.jaotus || []).length ? `<div class="pinna-jaotus">${s.jaotus.map(p => `<div><span>${escH(p.osa)}</span><b class="mono">${eur(p.m2, 1)} m²</b></div>`).join("")}</div>` : ""}
          <div class="pinna-jaotus">
            ${s.elekter ? `<div><span>Elektrivõimsus</span><b class="mono">${s.elekter} A</b></div>` : ""}
            <div><span>Parkimiskohad${parkOn(obj.id) && !isClient() && !s.jagatud ? ` <button type="button" class="steplink" onclick="parkPinnaMuuda('${s.id}')">Muuda</button>` : ""}</span><b class="mono">${(s.parkKohad || []).length ? "nr " + parkNrTxt(s.parkKohad) : s.parkimine ? s.parkimine + " kohta" : "—"}</b></div>
            ${kohad.length && kohad.join() !== (s.parkKohad || []).join() ? `<div><span>Lepingus <a class="steplink" href="#/leping/${lep.id}">${escH(lep.id)} →</a></span><b class="mono">nr ${parkNrTxt(kohad)}</b></div>` : ""}
          </div>
        </section>
      </aside>
    </div>
  </div>`;
};
View.pind.init = () => {
  const s = DB.spaceById((location.hash.match(/#\/pind\/(.+)/) || [])[1] || ""); if (!s) return;
  const rows = PF_ROWS.concat(arhiivLoend(pinnaDokRead(s).arh, "", { seisud: false }).rows);
  document.querySelectorAll(".op-docs [data-pfrow], .op-arh [data-pfrow]").forEach(el => el.onclick = (ev) => { if (ev.target.closest("a, button")) return; const r = rows[+el.dataset.pfrow]; if (r && r.href) location.hash = r.href; });
};
View.parkHaldus = viewParkHaldus;   /* v660: parkimiskohtade haldus (funktsioonid parkimise plokis) */
View.parkHaldus.init = () => pkhDraw();
/* pinna lehe toimingud: uus pakkumine sellele pinnale; kehtiva lepingu muudatusrežiim */
window.pindUusPak = (sid) => { const s = DB.spaceById(sid); if (!s) return; PRE_SPACE = s.id; PRE_OBJECT = objektOf(s).id; location.hash = "#/pakkumus-uus"; };
/* v794 (kasutaja 30.09: „pinna kustutamine ei ole vist hetkel võimalik"): pinna kustutamine pinna lehe toimingutes.
   Lubatud AINULT dokumendivabale pinnale — ka arhiveeritud leping, imporditud leping või lõppenud pakkumine hoiab pinda (ajalugu viitab
   sellele). Jagatud ema ja üksused → enne ühenda. Kinnitus + 10 s „Võta tagasi"; kustutamine ja taastamine lähevad sündmuslogisse. */
function pindKustutaKeeld(s) {
  if (!s) return "Pinda ei leitud.";
  if (s.jagatud) return "Pind on jagatud üksusteks — ühenda üksused enne tagasi.";
  if (s.emaId) return "See on jagatud pinna üksus — ühenda üksused ema-pinna lehel.";
  const l = LEASES.find(x => lepPohiPindIds(x).includes(s.id) || lepPindSeos(x, s.id));
  if (l) return `Pind on lepingus ${l.id}${lepArh(l) ? " (arhiivis)" : ""} — dokumendi ajalugu viitab sellele.`;
  const x = IMPORDITUD.find(y => (y.pindIds || []).includes(s.id));
  if (x) return `Pinnal on imporditud leping ${x.id} — dokumendi ajalugu viitab sellele.`;
  const o = OFFERS.find(y => (y.spaceIds || []).includes(s.id));
  if (o) return `Pind on pakkumises ${o.id} — dokumendi ajalugu viitab sellele.`;
  return null;
}
window.pindKustuta = async (sid) => {
  const s = DB.spaceById(sid), k = pindKustutaKeeld(s); if (k) { toast(k); return; }
  const obj = objektOf(s), kohad = (s.parkKohad || []).slice();
  if (!(await askConfirm(`Kustutad ${s.nimi} (${eur(s.yyripind, 1)} m²) objektilt ${obj.nimi}?${kohad.length ? ` Parkimiskohad nr ${parkNrTxt(kohad)} jäävad registrisse ilma pinnata.` : ""}`, "Kustuta pind"))) return;
  const i = SPACES.indexOf(s), koopia = JSON.parse(JSON.stringify(s));
  SPACES.splice(i, 1);
  AUDIT.unshift({ aeg: NOW_EE(), autor: "Tarmo Sepp", tegevus: `${s.nimi} kustutatud objektilt ${obj.nimi} (${eur(s.yyripind, 1)} m² · ${eur(s.hind || 0, 2)} €/m²${kohad.length ? ` · parkimiskohad nr ${parkNrTxt(kohad)} jäid pinnata` : ""}).` });
  if (!DB.save()) { SPACES.splice(i, 0, s); toast("Salvestamine ebaõnnestus — pind jäi alles."); return; }
  location.hash = "#/objekt/" + obj.id;
  toastTagasi(`${s.nimi} kustutatud`, () => {
    if (SPACES.some(x => x.id === koopia.id)) return;
    SPACES.splice(Math.min(i, SPACES.length), 0, koopia);
    AUDIT.unshift({ aeg: NOW_EE(), autor: "Tarmo Sepp", tegevus: `${koopia.nimi} taastatud objektile ${obj.nimi} (kustutamine tagasi võetud).` });
    DB.save(); toast(`${koopia.nimi} taastatud`); router(); });
};
window.pindMuudatus = (lid) => { LEP_FOCUS_ID = lid; LEP_MUUDATUS_MODE = true; location.hash = "#/leping/" + lid; };

View.osapool.init = () => {
  const rows = PF_ROWS.concat(osapoolById((location.hash.match(/#\/osapool\/(.+)/) || [])[1] || "") ? arhiivLoend(osapoolById(location.hash.split("/").pop()).arh, "", { seisud: false }).rows : []);
  document.querySelectorAll(".op-docs [data-pfrow], .op-arh [data-pfrow]").forEach(el => el.onclick = (ev) => { if (ev.target.closest("a, button")) return; const r = rows[+el.dataset.pfrow]; if (r && r.href) location.hash = r.href; });
};

/* ---------- Suhtlus: vestluste loend + lõim (üks CommunicationThread) --------
   Allikad: pakkumise lingi kommentaarid · lepingu punktikommentaarid ·
   kliendikonto vabavestlus. Vastamata vestlus ilmub automaatselt Avalehele. */
const suhAeg = (s) => { const [d, t] = String(s).split(" "); const dt = parseEE(d); if (t) { const [h, m] = t.split(":"); dt.setHours(+h || 0, +m || 0); } return dt; };
function suhtlusThreads() {
  const th = [];
  LEASES.forEach(l => {
    const msgs = [];
    (isClient() ? (l.arutelud || []) : lepAruNahtav(l)).forEach(c => {   /* ühendamine: vooru saatmata märkused ei leki */
      msgs.push({ who: c.algataja === "operaator" ? "op" : "client", autor: c.autor, aeg: c.aeg, tekst: c.tekst, ref: c.ref, staatus: aruPill(c) });
      if (c.lahendusTekst) msgs.push({ who: "op", autor: "Tarmo Sepp (operaator)", aeg: c.lahendusAeg || c.aeg, tekst: c.lahendusTekst, ref: c.ref });
    });
    (l.vestlus || []).forEach(m => msgs.push(m));
    if (msgs.length) { const cl = DB.clientById(l.clientId);
      th.push({ id: l.id, klient: cl.nimi, kontakt: cl.kontakt, docT: l.liik || "Üürileping", href: "#/leping/" + l.id, kind: "lease", doc: l, msgs,
        pending: lepAruNahtav(l).some(aruOotabOp) || (() => { const V = l.vestlus || []; return !!V.length && V[V.length - 1].who === "client"; })() }); }
  });
  OFFERS.forEach(o => {
    const msgs = [];
    const cl = DB.clientById(o.clientId);
    /* läbirääkimiste logi (v158+): ettepanekud ja vastused voorude kaupa */
    (o.labiraakimised || []).forEach(m => msgs.push({
      who: m.roll === "klient" ? "client" : "op", autor: m.autor, aeg: m.aeg, tekst: m.tekst,
      ref: m.roll === "klient" ? "ettepanek" : "vastus",
      staatus: m.roll === "klient" && o.staatus === "Kliendi ettepanek" && o.kliendiEttepanek === m.tekst ? "Ootel" : undefined }));
    /* vanem salvestus/seeme: ettepanek ilma logita — ära topelda */
    if (o.kliendiEttepanek && !(o.labiraakimised || []).some(m => m.tekst === o.kliendiEttepanek))
      msgs.push({ who: "client", autor: cl.kontakt + " (üürnik)", aeg: o.loodud, tekst: o.kliendiEttepanek, ref: "vabas vormis", staatus: "Ootel" });
    (o.vestlus || []).forEach(m => msgs.push(m));
    if (msgs.length) th.push({ id: o.id, klient: cl.nimi, kontakt: cl.kontakt, docT: "Pakkumine", href: "#/pakkumus/" + o.id, kind: "offer", doc: o, msgs,
      pending: o.staatus === "Kliendi ettepanek" });
  });
  th.forEach(x => x.msgs.sort((a, b) => suhAeg(a.aeg) - suhAeg(b.aeg)));
  th.sort((a, b) => suhAeg(b.msgs[b.msgs.length - 1].aeg) - suhAeg(a.msgs[a.msgs.length - 1].aeg));
  return th;
}

/* kolleegi demost (demo 4) ühendatud 29.09 — Suhtlus */
/* ===== SUHTLUS v637 ALGUS ===== */
/* ==========================================================================
   SUHTLUS (v637) — sama sisu ja loogika (üks CommunicationThread dokumendi kohta), tugevam kujundus:
   päis lausega („1 vestlus ootab sinu vastust"), vasakul loend (otsing · Ootab vastust / Kõik · avatar · dokument ·
   viimane sõnum · ootab N p), paremal lõim (päis avatari ja dokumendiga · päevaeraldajad · mullid nagu kliendiportaalis ·
   koostaja: fail · vastus · AI mustand · saada). Vastamata vestlus ilmub ise Avalehele.
   ========================================================================== */
let SUH_F = "";   /* "" = kõik vestlused, "ootel" = ootab sinu vastust */
function suhInit(n) {
  const w = String(n || "?").replace(/^(Osaühing|Aktsiaselts|AS|OÜ)\s+/i, "").replace(/\s+(OÜ|AS|MTÜ|SA)$/i, "").split(/\s+/).filter(Boolean);
  return (w.length > 1 ? w[0][0] + w[1][0] : (w[0] || "?").slice(0, 2)).toUpperCase();
}
function suhKuup(aeg) {   /* täna → kellaaeg, see aasta → pp.kk, muidu kuupäev */
  const [d, t] = String(aeg || "").split(" ");
  return d === TODAY_EE ? (t || "täna") : d && d.slice(6) === TODAY_EE.slice(6) ? d.slice(0, 5) : (d || "");
}
function suhRida(x, sel) {
  const last = x.msgs[x.msgs.length - 1], p = x.pending ? Math.max(0, -daysUntil(String(last.aeg).split(" ")[0])) : 0;
  return `<a class="suh2-r${sel ? " sel" : ""}${x.pending ? " ootel" : ""}" href="#/suhtlus/${x.id}" data-sl="${x.pending ? "ootel" : ""}"${sel ? ' aria-current="true"' : ""}>
      <span class="suh2-av">${escH(suhInit(x.klient))}</span>
      <span class="suh2-r-tx">
        <span class="suh2-r-1"><b>${escH(x.klient)}</b><time>${escH(suhKuup(last.aeg))}</time></span>
        <span class="suh2-r-doc">${escH(x.docT)} · ${escH(x.id)}</span>
        <span class="suh2-r-msg">${last.who === "op" ? "Sina: " : ""}${escH(last.tekst)}</span>
        ${x.pending ? `<span class="suh2-r-st"><i></i>Ootab sinu vastust${p >= 1 ? ` · ${p} p` : ""}</span>` : ""}
      </span></a>`;
}
function suhLoim(sel) {
  let eel = "";
  const read = sel.msgs.map(m => {
    const paev = String(m.aeg || "").split(" ")[0], kell = String(m.aeg || "").split(" ")[1] || "";
    const sep = paev && paev !== eel ? `<div class="suh2-paev"><span>${paev === TODAY_EE ? "Täna" : escH(paev)}</span></div>` : "";
    if (paev) eel = paev;
    /* viide nagu dokumendis: „p 4.1" (põhitingimuse ref on juba „P 4.1" — ei topelda) */
    const refT = (r) => /^p\s/i.test(r) ? "p " + r.replace(/^p\s+/i, "") : /^\d/.test(r) ? "p " + r : r;
    const ref = m.ref ? (sel.kind === "lease" ? `<button type="button" class="suh2-ref" onclick="openLepingPunkt('${sel.id}','${escH(m.ref)}')" title="Ava punkt lepingus">${escH(refT(m.ref))}</button>` : `<span class="suh2-ref">${escH(m.ref)}</span>`) : "";
    const ootab = m.staatus === "Ootel" && m.who === "client";
    return sep + `<div class="suh2-m${m.who === "op" ? " mina" : ""}">
          <div class="suh2-mb">${ref}<span>${escH(m.tekst)}</span></div>
          <div class="suh2-mm">${escH(String(m.autor || "").replace(/\s*\((operaator|üürileandja|üürnik)\)$/, ""))}${kell ? ` · ${escH(kell)}` : ""}${ootab ? ` · <em><i></i>ootab vastust</em>` : ""}</div>
        </div>`;
  }).join("");
  return `
      <section class="card suh2-loim">
        <header class="suh2-pea">
          <span class="suh2-av suur${sel.pending ? " ootel" : ""}">${escH(suhInit(sel.klient))}</span>
          <div class="suh2-pea-tx"><b>${escH(sel.klient)}</b>
            <span>${sel.kontakt ? `${escH(sel.kontakt)} · ` : ""}<a href="${sel.href}">${escH(sel.docT)} ${escH(sel.id)}</a>${sel.pending ? ` · <em><i></i>Ootab sinu vastust</em>` : ""}</span></div>
          <a class="btn btn-ghost btn-sm suh2-ava" href="${sel.href}">Ava ${sel.kind === "offer" ? "pakkumine" : "leping"}<span class="bic">${I.arrow}</span></a>
        </header>
        ${p8SuhSamm(sel)}
        <div class="suh2-msgs" id="suh-msgs">${read}</div>
        <footer class="suh2-kirj">
          <div class="suh2-komp">
            <button type="button" class="suh2-ic" title="Lisa fail" aria-label="Lisa fail" onclick="toast('Faili lisamine vestlusse — demos illustratiivne')">${I.clip}</button>
            <textarea id="suh-in" rows="1" placeholder="Kirjuta vastus…" aria-label="Vastus"></textarea>
            <button type="button" class="suh2-ai" id="suh-ai" title="AI koostab mustandi — toimeta ja saada">${I.spark}<span>AI mustand</span></button>
            <button type="button" class="suh2-saada" id="suh-send" title="Saada (Enter)" aria-label="Saada">${I.up}</button>
          </div>
          <p class="suh2-vihje">AI koostab mustandi — toimetad ja saadad ise. Enter saadab, Shift + Enter uus rida.</p>
        </footer>
      </section>`;
}
View.suhtlus = (tid) => {
  const th = suhtlusThreads(), ootel = th.filter(x => x.pending).length;
  const sel = th.find(x => x.id === tid) || th.find(x => x.pending) || th[0];
  const lause = !th.length ? "Vestlusi veel pole — need tekivad pakkumiste ja lepingute juures."
    : ootel ? `<b>${ootel === 1 ? "1 vestlus ootab" : ootel + " vestlust ootavad"} sinu vastust</b> · kokku ${th.length}` : `<b>Kõigile on vastatud.</b> Kokku ${th.length === 1 ? "1 vestlus" : th.length + " vestlust"}.`;
  const siin = "#/suhtlus" + (sel ? "/" + sel.id : "");
  return `
  <div class="view suh2">
    <div class="pf-head reveal"><div><h1 class="page-h1">Suhtlus</h1><p class="pf-lead suh2-lause">${lause}</p></div></div>
    <div class="suh2-grid reveal">
      <aside class="card suh2-list" aria-label="Vestlused">
        <div class="suh2-list-pea">
          <div class="pf-search">${I.search}<input id="suh-q" placeholder="Otsi osapoolt või dokumenti…" autocomplete="off" aria-label="Otsi vestlust"/></div>
          <div class="pf-subtabs suh2-f"><a href="${siin}" data-sf="ootel" class="${SUH_F === "ootel" ? "on" : ""}">Ootab vastust${arvMark(ootel)}</a><a href="${siin}" data-sf="" class="${SUH_F ? "" : "on"}">Kõik${arvMark(th.length)}</a></div>
        </div>
        <div class="suh2-read">${th.map(x => suhRida(x, sel && x.id === sel.id)).join("")}
          <div class="suh2-tyhi" id="suh-tyhi"${th.length ? " hidden" : ""}>${th.length ? "Selle filtriga vestlusi pole." : "Vestlusi veel pole."}</div></div>
      </aside>
      ${sel ? suhLoim(sel) : `<section class="card suh2-loim suh2-loim-tyhi"><span class="suh2-tyhi-ic">${I.chat}</span><b>Vestlusi veel pole</b><p>Kliendi kommentaarid ja ettepanekud pakkumiste ning lepingute juures ilmuvad siia.</p></section>`}
    </div>
  </div>`;
};
View.suhtlus.init = (tid) => {
  const th = suhtlusThreads();
  const sel = th.find(x => x.id === tid) || th.find(x => x.pending) || th[0];
  /* otsing + Ootab vastust | Kõik */
  const q = document.getElementById("suh-q"), tyhi = document.getElementById("suh-tyhi");
  const apply = () => {
    const v = q ? q.value.trim().toLowerCase() : ""; let n = 0;
    document.querySelectorAll(".suh2-f [data-sf]").forEach(b => b.classList.toggle("on", b.dataset.sf === SUH_F));
    document.querySelectorAll(".suh2-r").forEach(r => { const hit = (!v || (r.textContent || "").toLowerCase().includes(v)) && (!SUH_F || r.dataset.sl === SUH_F); r.hidden = !hit; if (hit) n++; });
    if (tyhi && th.length) tyhi.hidden = n > 0;
  };
  if (q) q.addEventListener("input", apply);
  document.querySelectorAll(".suh2-f [data-sf]").forEach(b => b.onclick = (ev) => { ev.preventDefault(); SUH_F = b.dataset.sf; apply(); });
  apply();
  const ms = document.getElementById("suh-msgs"); if (ms) ms.scrollTop = ms.scrollHeight;
  if (!sel) return;
  /* saatmine: sõnum läheb dokumendi CommunicationThread'i */
  const inp = document.getElementById("suh-in");
  const send = () => {
    const v = inp ? inp.value.trim() : "";
    if (!v) return;
    if (sel.kind === "offer") {
      /* pakkumise lõim = läbirääkimiste logi — sama ajalugu, mida näeb klient pakkumisvaates */
      (sel.doc.labiraakimised = sel.doc.labiraakimised || []).push({ roll: "operaator", autor: "Tarmo Sepp (üürileandja)", tekst: v, aeg: NOW_EE() });
    } else {
      sel.doc.vestlus = sel.doc.vestlus || [];
      sel.doc.vestlus.push({ who: "op", autor: "Tarmo Sepp (operaator)", aeg: NOW_EE(), tekst: v });
    }
    AUDIT.unshift({ aeg: NOW_EE(), autor: "Tarmo Sepp", tegevus: `${sel.id}: sõnum saadetud kliendile (CommunicationThread).` });
    DB.save(); toast("Saadetud kliendile"); router();
  };
  const sb2 = document.getElementById("suh-send");
  if (sb2) sb2.onclick = send;
  const kasva = () => { if (!inp) return; inp.style.height = "auto"; inp.style.height = Math.min(inp.scrollHeight, 168) + "px"; };
  if (inp) { inp.addEventListener("input", kasva); inp.addEventListener("keydown", e => { if (e.key === "Enter" && !e.shiftKey && !e.isComposing) { e.preventDefault(); send(); } }); }
  /* AI-mustand: eeltäidab sisendi, operaator toimetab ja saadab ise */
  const ai = document.getElementById("suh-ai");
  if (ai) ai.onclick = () => {
    const last = [...sel.msgs].reverse().find(m => m.who === "client");
    const eesnimi = (sel.kontakt || "").split(" ")[0];
    const sisu = last && /tagatis/i.test(last.tekst)
      ? "Saame pakkuda tagatisraha vähendamist 2 kuu üürile tingimusel, et lepingu tähtaeg on vähemalt 5 aastat — vormistame selle eritingimusena (Lisa 3)."
      : last && /indeks|thi/i.test(last.tekst)
      ? "THI-põhine indekseerimine sobib — vormistame selle eritingimusena, mis kirjutab üle üldtingimuste p 5.2."
      : "Vaatasime Teie ettepaneku üle ja tuleme lahendusega tagasi järgmises mustandis. Kokkulepe vormistatakse eritingimusena (Lisa 3).";
    if (inp) { inp.value = `Tere, ${eesnimi}!\n\nTäname tagasiside eest${last && last.ref && last.ref !== "vabas vormis" ? ` punkti ${last.ref} kohta` : ""}. ${sisu}\n\nParimate soovidega\nTarmo Sepp`; kasva(); if (inp.focus) inp.focus(); }
    toast("AI mustand valmis — toimeta ja saada");
  };
};
/* ===== SUHTLUS v637 LÕPP ===== */

