function seDokumendid() {
  const o = OBJEKTID[0] || { mallid: {} }, m = o.mallid || {};
  const imp = typeof window.impMallid === "function" ? window.impMallid() : [];
  const ver = (t) => (String(t || "").match(/v[\d.]+/) || [""])[0];
  const pohjad = [
    m.uldtingimused ? seR(seIc("page"), escH(String(m.uldtingimused).replace(/\s*\(lukus\)$/, "")), `${ver(m.uldtingimused) || "v1.0"} kehtiv · lepingus lukus, muudatus ainult uue versiooniga`, `<button type="button" class="se-link" data-mall="uld">Ava</button>`) : "",
    m.eritingimused ? seR(seIc("edit"), escH(m.eritingimused), "lähtepunkt — operaator kohandab tehingus", `<button type="button" class="se-link" data-mall="eri">Ava</button>`) : "",
    m.pakkumus ? seR(seIc("offer"), escH(m.pakkumus), "pakkumise dokumendi põhi", `<button type="button" class="se-link" data-mall="pakk">Ava</button>`) : "",
    ...imp.map(f => seR(seIc("file"), "Äriruumide üürileping — põhi (Word)", `imporditud ${escH((f.mallSalvestatud || {}).aeg || "")} · ${(f.mallSalvestatud || {}).valjad || 0} täidetavat välja`, `<a class="se-link" href="#/import/${f.id}">Ava</a>`)),
  ].join("");
  const v = seVaike();
  const vali = (k, L) => `<select class="se-in vk-in" data-vk="${k}" aria-label="${k}">${L.map(([val, tx]) => `<option value="${val}"${String(v[k]) === String(val) ? " selected" : ""}>${tx}</option>`).join("")}</select>`;
  return `<div class="se-grid">
      <div class="se-veerg">
      ${seP("Mallid", "Millest dokumendid ja kirjad algavad?", `<div class="se-g">Lepingu põhjad</div>${pohjad}<div class="se-g">E-kirjade mallid</div>`
        + SE_KIRJAD.map(k => seR(seIc("send"), k.t, k.s, `<button type="button" class="se-link" data-kiri="${k.k}">Eelvaade</button>`)).join(""),
        seLisa("Impordi Wordist", ' data-href="#/import"'))}
      </div>
      <div class="se-veerg">
      ${seP("Üldtingimused", "Millised üldtingimused kehtivad uutele lepingutele?", SE_ULD.map(u => seR(seIc("page"), `v${u.v}${u.kehtiv ? ` <span class="se-chip on">kehtiv</span>` : ""}`,
          `${u.lopp ? `${u.alates} – ${u.lopp}` : `alates ${u.alates}`} · ${escH(u.s)}`, u.kehtiv ? `<button type="button" class="se-link" data-mall="uld">Ava tekst</button>` : `<span class="se-aeg">varem sõlmitud</span>`)).join(""),
        `<p class="se-noot">Uus versioon kehtib ainult uutele lepingutele — kehtivad lepingud jäävad oma versioonile.</p>`)}
      ${seP("Pakkumise vaikeväärtused", "Millest uus pakkumine algab? Igas pakkumises saab muuta.",
        seR(seIc("cal"), "Periood", "üüriperioodi pikkus", vali("pikkusKuud", [12, 24, 36, 60, 120].map(x => [x, x + " kuud"])))
        + seR(seIc("shield"), "Tagatis", "kuu üüri kordades", vali("tagatisKuud", [1, 2, 3, 6].map(x => [x, x + " kuu üür"])))
        + seR(seIc("trend"), "Indekseerimine", "üüri muutus kord aastas", vali("indeks", Object.entries(SE_INDEKS)))
        + seR(seIc("clock"), "Pakkumise kehtivus", "päeva saatmisest", `<span class="se-num lai"><input class="vk-in" data-vk="kehtivusPaevi" type="number" min="1" max="90" value="${v.kehtivusPaevi}" inputmode="numeric" aria-label="Kehtivus päevades"><span>päeva</span></span>`))}
      </div>
    </div>`;
}
function seAutomaatika() {
  return `<div class="se-auto reveal"><span class="se-auto-ic">${I.spark}</span><p><b>Platvorm teeb ise:</b> loeb Statistikaameti indeksi ja indekseerib üüri, tuletab meelde tähtajad ja vastamata pakkumised ning kontrollib klientide riskiskoori. Sina otsustad ainult seal, kus on vaja inimest.</p></div>
    <div class="se-grid">
      ${seP("Integratsioonid", "Kust platvorm andmeid ise loeb?", SE_INTEG.map(x => { const o = seOlek(x);
        return seR(seIc(x.ic), x.t, `${x.s}${o === "viga" ? `<span class="se-viga-r">Päring aegus · <button type="button" class="se-link" data-int-uuesti="${x.k}">Proovi uuesti</button></span>` : ""}`,
          `<span class="se-olek ${o}"><i></i>${SE_OLEK[o]}</span><span class="se-aeg">${x.viimane}</span>`, ` data-int="${x.k}" role="button" tabindex="0"`); }).join(""))}
      ${seP("Teavitused", "Kui vara tähtajast märku antakse?", TEAVITUSED_DEF.map(d => seR(seIc(d.ic), d.t, d.s,
          `<span class="se-num"><input class="tv-in" data-tv="${d.k}" value="${SEADED.teavitused[d.k]}" inputmode="numeric" aria-label="${d.t} — ${d.yhik || "päeva ette"}"><span>${d.yhik || "päeva ette"}</span></span>`)).join(""),
        `<p class="se-noot">Vaikeajad kehtivad uutele tähtaegadele; üksikul lepingul saab aega eraldi muuta. Kõik teavitused lähevad ka meilile — operaatorile tööpostkasti, kliendile tema kontaktile.</p>`)}
    </div>`;
}
View.seaded = (arg) => {
  const tab = SE_SAKID.some(([k]) => k === arg) ? arg : "ettevote";
  const sisu = tab === "dokumendid" ? seDokumendid() : tab === "automaatika" ? seAutomaatika() : seEttevote();
  return `
  <div class="view se">
    <div class="pf-head reveal"><div><h1 class="page-h1">Seaded</h1><p class="pf-lead">Kolm rühma: ettevõte, dokumendid ja see, mida platvorm teeb ise.</p></div></div>
    <nav class="pf-tabs reveal" aria-label="Seadete lehed">${SE_SAKID.map(([k, t]) => `<a class="${k === tab ? "active" : ""}" href="#/seaded/${k}"${k === tab ? ' aria-current="page"' : ""}>${t}</a>`).join("")}</nav>
    <div class="reveal">${sisu}</div>
  </div>`;
};
/* külgpaneel (vormid ja detailid) — sama kest mis mujal platvormil */
/* ==========================================================================
   v797 (kasutaja 30.09: „pinnaandmed tulevad tabelist, jooniste lisamine on ainult käsitsi"): PLAANIDE HULGI-ÜLESLAADIMINE.
   Lohista/vali palju faile korraga (PDF · PNG · JPG · SVG · ZIP) → sidumine FAILINIME järgi (T6B_Pind_08.pdf → Pind 8, …_B1 → B1)
   → eelvaade „fail → pind" (vaste / vali käsitsi / jäta välja) → kinnita. Failid IndexedDB-s (IMP_IDB, sama mis impordi originaalid;
   localStorage-isse ei mahuks), pinnal `plaanFail = "idb:plaan:<pind>:<räsi>.<laiend>"`; openPdf, lisa eelvaade ja ASiC-E loevad seda.
   Iga seotud plaan läheb sündmuslogisse. Allkirjastatud/koostatud dokumendid hoiavad oma lisa (ei muutu).
   v801: üleslaadimine elab objekti töövoo sammus „Plaanid” (owPlLisa/owPlaanid); siia jäid sidumisreeglid.
   ========================================================================== */
const PL_LAIEND = { pdf: "application/pdf", png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", svg: "image/svg+xml" };
/* võti: „Pind 8" → 8 · „Büroo 3"/„Boks 3"/„B3" → B3 (T6B failides B1–B5 = Büroo 1–5) */
const plVoti = (eesl, v) => { v = String(v).toUpperCase().replace(/^0+(?=\d)/, ""); return /^(büroo|buroo|boks|box|b)$/i.test(eesl || "") && /^\d/.test(v) ? "B" + v : v; };
const plPinnaVoti = (s) => { const m = String(s.nimi || "").trim().match(/^(pind|boks|büroo|buroo|ladu|p)?\s*([A-Z]?\d{1,3}[A-Z]?)$/i); return m ? plVoti(m[1], m[2]) : String(s.nimi || "").toUpperCase(); };
function plVaste(nimi, pinnad) {
  const b = String(nimi).replace(/\.[^.]+$/, "").replace(/[_\-.]+/g, " ");
  const m = b.match(/(pind|p|unit|space|boks|box|büroo|buroo)\s*0*([A-Z]?\d{1,3}[A-Z]?)\b/i) || b.match(/\b()(B\d{1,2})\b/i);
  if (!m) return null;
  const v = plVoti(m[1], m[2]);
  return pinnad.find(s => plPinnaVoti(s) === v) || null;
}
function sePaneel({ overline, pealkiri, sub, body, foot }) {
  const head = document.getElementById("side-head"), b = document.getElementById("side-body"), f = document.getElementById("side-foot"); if (!head || !b || !f) return;
  head.innerHTML = `${overline ? `<div class="overline">${overline}</div>` : ""}<div class="se-sp-t">${pealkiri}</div>${sub ? `<div class="se-sp-s">${sub}</div>` : ""}`;
  b.innerHTML = body || "";
  f.innerHTML = foot || `<button class="btn btn-ghost" style="width:100%;justify-content:center" onclick="closeSide()">Sulge</button>`;
  document.getElementById("side").classList.add("open"); document.getElementById("scrim").classList.add("open");
}
function seKiriNaidis(k) { return seKiriNaidis0(k); }   /* ühendamine: etapis 6 (kirjad) sama funktsioon, mis saadab (p8KiriNaidis) */
function seKiriNaidis0(k) {
  const o = OFFERS.find(x => x.staatus === "Saadetud") || OFFERS[0], cl = o ? DB.clientById(o.clientId) : null, en = cl ? String(cl.kontakt || "").split(" ")[0] : "";
  const l = LEASES.find(x => x.staatus === "Allkirjastamisel") || LEASES[0], cl2 = l ? DB.clientById(l.clientId) : null;
  const saatja = ACCOUNT.landlord.nimi;
  if (k === "allkiri") return { teema: `Leping ${l ? l.id : ""} ootab allkirja`, tekst: `Tere${cl2 && cl2.kontakt ? ", " + String(cl2.kontakt).split(" ")[0] : ""}!\n\nÜürileping ${l ? l.id : ""} on valmis allkirjastamiseks. Allkirjastada saad Smart-ID, Mobiil-ID või ID-kaardiga — link avab lepingu ja allkirjastamise akna.\n\nLugupidamisega\n${saatja}` };
  if (k === "meeldetuletus") return { teema: `Pakkumine ${o ? o.id : ""} aegub peagi`, tekst: `Tere${en ? ", " + en : ""}!\n\nTuletame meelde, et pakkumine ${o ? o.id : ""} kehtib kuni ${o ? o.kehtivKuni : ""}. Kui soovid midagi muuta, saad ettepaneku teha otse pakkumises.\n\nLugupidamisega\n${saatja}` };
  return { teema: `Pakkumine ${o ? o.id : ""} — ${cl ? cl.nimi : ""}`, tekst: `Tere${en ? ", " + en : ""}!\n\nSaadame Teile pakkumise ${o ? o.id : ""}. Lingilt näed tingimusi, saad teha ettepanekuid ja pakkumise aktsepteerida.\n\nPakkumine kehtib kuni ${o ? o.kehtivKuni : ""}.\n\nLugupidamisega\n${saatja}` };
}
function seLae(nimi, sisu, tyyp) {
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([sisu], { type: `${tyyp};charset=utf-8` }));
  a.download = nimi; document.body.appendChild(a); a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 0);
}
View.seaded.init = () => {
  /* ettevõtte aktsentvärv, eemaldamine, kutse tühistamine */
  document.querySelectorAll(".ett-varv").forEach(inp => inp.onchange = () => {
    SEADED.varvid[inp.dataset.cid] = inp.value; seadSave();
    toast("Aktsentvärv salvestatud — rakendub dokumentidel ja kliendilingil"); router();
  });
  document.querySelectorAll("[data-ett-rm]").forEach(b => b.onclick = () => { SEADED.lisatud.splice(+b.dataset.ettRm, 1); seadSave(); toast("Ettevõte eemaldatud"); router(); });
  document.querySelectorAll("[data-kutse-rm]").forEach(b => b.onclick = () => { SEADED.kutsed.splice(+b.dataset.kutseRm, 1); seadSave(); toast("Kutse tühistatud"); router(); });
  /* teavituste vaikeajad ja pakkumise vaikeväärtused salvestuvad kohe */
  document.querySelectorAll(".tv-in").forEach(inp => inp.onchange = () => {
    const v = parseInt(inp.value, 10);
    if (!isFinite(v) || v < 1) { inp.value = SEADED.teavitused[inp.dataset.tv]; return; }
    SEADED.teavitused[inp.dataset.tv] = v; seadSave(); toast("Teavituse vaikeaeg salvestatud: " + v + " päeva ette");
  });
  document.querySelectorAll(".vk-in").forEach(inp => inp.onchange = () => {
    const k = inp.dataset.vk, v = k === "indeks" ? inp.value : parseInt(inp.value, 10);
    if (k !== "indeks" && !(v > 0)) { inp.value = seVaike()[k]; return; }
    SEADED.vaike = Object.assign({}, seVaike(), { [k]: v }); seadSave();
    toast("Vaikeväärtus salvestatud — uued pakkumised algavad sellest; igas pakkumises muudetav");
  });
  /* mallid ja kirjade eelvaade */
  document.querySelectorAll("[data-mall]").forEach(b => b.onclick = () => p8MallAva(b.dataset.mall));   /* v644 (25d) */
  document.querySelectorAll("[data-kiri]").forEach(b => b.onclick = () => { const mall = SE_KIRJAD.find(x => x.k === b.dataset.kiri), k = seKiriNaidis(b.dataset.kiri);
    sePaneel({ overline: "E-kirja mall", pealkiri: mall.t, sub: mall.s, body: `<div class="se-kiri"><div class="se-kiri-pea"><small>Saatja</small><b>${escH(ACCOUNT.landlord.nimi)}</b><small>Teema</small><b>${escH(k.teema)}</b></div><div class="se-kiri-tx">${escH(k.tekst)}</div></div>` }); });
  document.querySelectorAll("[data-href]").forEach(b => b.onclick = () => { location.hash = b.dataset.href; });
  /* andmete eksport */
  document.querySelectorAll("[data-eksport]").forEach(b => b.onclick = () => p8Eksport(b.dataset.eksport));   /* v644 (18): eelvaade enne allalaadimist */
  /* integratsioonid: rida avab detaili, „Proovi uuesti" taastab ühenduse */
  const uuesti = (k) => { const x = SE_INTEG.find(i => i.k === k); if (!x) return;
    SEADED.integ = Object.assign({}, SEADED.integ, { [x.k]: "ok" }); seadSave();
    AUDIT.unshift({ aeg: NOW_EE(), autor: "Tarmo Sepp", tegevus: `Integratsioon ${x.t}: päring korrati — ühendus taastus.` }); DB.save();
    closeSide(); toast(`${x.t}: ühendus taastus — viimane päring õnnestus`); router(); };
  document.querySelectorAll("[data-int-uuesti]").forEach(b => b.onclick = (ev) => { ev.stopPropagation(); uuesti(b.dataset.intUuesti); });
  document.querySelectorAll("[data-int]").forEach(r => { const ava = () => { const x = SE_INTEG.find(i => i.k === r.dataset.int); if (!x) return; const o = seOlek(x);
      sePaneel({ overline: "Integratsioon", pealkiri: x.t, sub: x.s, body: `
        <div class="se-kv"><span>Seis</span><b><span class="se-olek ${o}"><i></i>${SE_OLEK[o]}</span></b><span>Viimane päring</span><b>${x.viimane}</b></div>
        <div class="se-kv-l">Kus seda kasutatakse</div><p class="se-kv-p">${x.kus}</p>
        ${o === "viga" ? `<div class="se-viga">${I.warn}<span>${x.viga}</span></div>` : ""}`,
        foot: o === "viga" ? `<button class="btn btn-primary" style="width:100%;justify-content:center" id="se-int-uuesti">Proovi uuesti</button>` : "" });
      const u = document.getElementById("se-int-uuesti"); if (u) u.onclick = () => uuesti(x.k); };
    r.onclick = ava; r.onkeydown = (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); ava(); } }; });
  /* vormid külgpaneelis: ettevõtte lisamine (äriregistri autotäide) ja kasutaja kutse */
  document.querySelectorAll("[data-se]").forEach(b => b.onclick = () => {
    if (b.dataset.se === "ett") {
      sePaneel({ overline: "Ettevõtted", pealkiri: "Lisa ettevõte", sub: "Otsi e-äriregistrist — nimi, aadress ja KMKR täidetakse ise.", body: `
        <label class="se-f"><span>Registrikood</span><input id="ett-reg" class="se-in" placeholder="nt 10633207" inputmode="numeric" autocomplete="off"></label>
        <button type="button" class="btn btn-primary" id="ett-otsi" style="width:100%;justify-content:center;margin-top:12px">Otsi äriregistrist</button>
        <div id="ett-leid"></div>
        <p class="se-noot">Logo ja aktsentvärv lähevad dokumentidele — pakkumine, leping, kliendilink.</p>` });
      const otsi = document.getElementById("ett-otsi"), leid = document.getElementById("ett-leid");
      otsi.onclick = () => { const reg = (document.getElementById("ett-reg").value || "").trim();
        if (!/^\d{8}$/.test(reg)) { toast("Registrikood on 8-kohaline number"); return; }
        const nimi = "Kolmas Kinnisvara OÜ";
        leid.innerHTML = `<div class="se-leid"><small>e-äriregister · autotäide</small><b>${nimi}</b><span>reg ${reg} · KMKR EE10${reg.slice(0, 6)} · Pärnu mnt 15, Tallinn</span>
          <button type="button" class="btn btn-primary btn-sm" id="ett-lisa">${I.plus} Lisa kontole</button></div>`;
        document.getElementById("ett-lisa").onclick = () => { SEADED.lisatud.push({ reg, nimi }); seadSave();
          AUDIT.unshift({ aeg: NOW_EE(), autor: "Tarmo Sepp", tegevus: `Ettevõte ${nimi} (reg ${reg}) lisatud kontole e-äriregistri autotäitega.` }); DB.save();
          closeSide(); toast("Ettevõte lisatud — järgmised sammud: logo, aktsentvärv ja portfelli import"); router(); }; };
    } else if (b.dataset.se === "kutse") {
      sePaneel({ overline: "Kasutajad", pealkiri: "Kutsu kasutaja", sub: "Kutse läheb e-postile ja kehtib 7 päeva.", body: `
        <label class="se-f"><span>E-post</span><input id="ku-epost" class="se-in" type="email" placeholder="nimi@ettevote.ee" autocomplete="off"></label>
        <label class="se-f"><span>Roll</span><select id="ku-roll" class="se-in"><option>Operaator</option><option>Admin</option></select></label>
        <p class="se-noot">Admin — seaded, kasutajad ja mallid. Operaator — igapäevane tehingutöö.</p>`,
        foot: `<button class="btn btn-primary" style="width:100%;justify-content:center" id="ku-saada">${I.send} Saada kutse</button>` });
      document.getElementById("ku-saada").onclick = () => { const e = plainIn(document.getElementById("ku-epost").value);
        if (!/^\S+@\S+\.\S+$/.test(e)) { toast("Sisesta korrektne e-posti aadress"); return; }
        const roll = document.getElementById("ku-roll").value;
        SEADED.kutsed.push({ epost: e, roll, aeg: NOW_EE() }); seadSave();
        AUDIT.unshift({ aeg: NOW_EE(), autor: "Tarmo Sepp", tegevus: `Kasutajakutse saadetud: ${e} (${roll}).` }); DB.save();
        closeSide(); toast("Kutse saadetud e-postile — kehtib 7 päeva"); router(); };
    }
  });
};
