function router() {
  setMobileNav(false, false);
  document.querySelectorAll('.drop.open').forEach(el => el.classList.remove('open'));
  document.getElementById('loo-btn')?.classList.remove('open');
  let h = location.hash || "#/";
  /* v583: vana lepingute leht (#/lepingud[/filter]) pole enam kasutusel — kõik lingid viivad portfelli lepingute vaatesse */
  const vanaLep = h.match(/^#\/lepingud(?:\/([\w-]+))?$/);
  if (vanaLep) { const f = vanaLep[1]; h = "#/portfell/lepingud" + (/^(mustand|labiraakimisel|allkirjastamisel)$/.test(f || "") ? "/labiraakimisel" : "");
    history.replaceState(null, "", h); }
  // kliendirežiimis on avaleht portaal
  if (isClient() && /^#?\/?$/.test(h)) h = "#/portaal";
  closeSide(); closePdf();
  p6Sync();   /* v642: platvormi lepingute tähtajad (indekseerimine, lõpp) KEY_DATES-is */
  logiPaigalda();   /* v790: sündmuslogi — iga AUDIT-i kirje saab struktuuri (invariant 1) */
  let route = ROUTES.find(r => r.re.test(h)) || ROUTES[0];
  const m = h.match(route.re);
  const arg = m && m[1];
  lepPubTaasta();   /* v707: eelmise renderduse hetktõmmis tagasi elavaks */
  if (/^#\/leping\//.test(h)) { const lv = DB.leaseById(arg); if (lv) { lepVoorEnsure(lv); if (lepVoorOotab(lv)) lepPubPane(lv); } }
  document.body.classList.toggle("voor-oota", !!LEP_SWAP);
  CURRENT_LEASE = /^#\/leping\//.test(h) ? DB.leaseById(arg) : null;

  /* avanemiskoreograafia AINULT vaatevahetusel: sama vaate uuesti-renderdus
     (iga tegevuse järel) EI käivita reveal-animatsioone uuesti — vaade püsib paigal */
  const appView = document.getElementById("app-view");
  /* route.key: filtri-alamteega vaated (portfell, lepingud, kalender …) loevad
     ÜHEKS vaateks — filtrivahetus ei ole vaatevahetus */
  const vKey = route.key || h;
  const viewChanged = LAST_VIEW_KEY !== vKey;
  appView.classList.toggle("re-render", !viewChanged);
  LAST_VIEW_KEY = vKey;
  appView.innerHTML = route.view(arg);
  /* v623: tühjal kontol ütleb iga põhileht, kus seadistus pooleli on */
  if (alPooleli() && /^#\/(ylevaade|portfell|kalender|suhtlus)/.test(h)) { const av = appView.querySelector(".view"); if (av) av.insertAdjacentHTML("afterbegin", alRibaHTML()); }
  document.getElementById("nav").innerHTML = renderNav(route.nav);
  { const lg = document.getElementById("sb-logi"); if (lg) lg.classList.toggle("on", route.nav === "#/audit"); }
  /* v583: murupuru esimene osa on link — „Portfell" viib tagasi selle saki juurde, kust dokument avati */
  const crumbLink = (txt) => txt.replace(/^(Portfell|Minu dokumendid)( › )/, (m, t, sep) =>
    `<a class="crumb-a" href="${t === "Portfell" ? "#/portfell/" + navSubOf(h) : "#/portaal"}">${t}</a>${sep}`);
  /* v640 (kolleeg): üürniku deal room — murupuru asemel üürileandja bränd */
  document.getElementById("crumb").innerHTML = isClient()
    ? p4DrBrand()   /* v776 (kasutaja): „Minu dokumendid” on dokumendi kohal kleepuv nupp (drKleep), mitte päises */
    : `ThinkOne <b>/</b> ${crumbLink(route.crumb)}`;
  /* avalehel on suur komposer — kompaktne ülariba-oma on seal peidus */
  document.body.classList.toggle("dash-shell", !isClient() && (/^#?\/?$/.test(h) || /^#\/(agent|ai)$/.test(h)));
  /* kliendirollis pole operaatori tööriistu: otsing + „Loo" on peidus */
  document.body.classList.toggle("client-shell", isClient());
  /* v487 (UX-test O8): „Vaata üürnikuna" on mõttekas ainult pakkumuse/lepingu juures (klient näeb nuppu alati) */
  document.body.classList.toggle("role-ctx", isClient() || /^#\/(pakkumus|pakkumus-doc|leping)\//.test(h));
  /* üles keritakse AINULT vaatevahetusel — sama vaate uuesti-renderdus (faktimuutus,
     otsus, kinnitus) jätab kasutaja täpselt sinna, kus ta oli */
  if (viewChanged) window.scrollTo(0,0);
  if (route.init) route.init(arg);
  /* v576: vaatevahetus on ekraanilugejale kuuldav (aria-live) ja fookus liigub põhisisule (ilma kerimiseta) */
  if (viewChanged) {
    const live = document.getElementById("sr-live"), crumb = document.getElementById("crumb");
    if (live) live.textContent = "Avatud: " + (crumb ? crumb.textContent.replace(/^ThinkOne\s*\/\s*/, "").replace(/KLIENDIPORTAAL/, "").trim() : "");
    if (document.activeElement === document.body || !document.activeElement || !appView.contains(document.activeElement)) {
      const omni = document.getElementById("omni-in");
      if (document.activeElement !== omni) appView.focus({ preventScroll: true });
    }
  }
  bindCoach(); /* esmakordsed vihjed: seotakse pärast vaate init-i, sest paan renderdub seal */
  /* paigutusreegel: kui vaates on otsuse-/läbirääkimiste paan, reserveeri sellele
     akna parem serv (paan ise on fixed) — sisu jääb ülejäänud alal keskele */
  document.body.classList.toggle("has-panel", !!appView.querySelector(".cl-side"));
  document.title = `${route.crumb} · ThinkOne`;
  appView.querySelectorAll('.ns-item[onclick], .pf-card, .kal-row.clickable[onclick], tr.clickable, .ci[onclick], .kd-item[onclick]').forEach(el => {
    el.tabIndex = 0;
    if (el.tagName !== 'TR') el.setAttribute('role', 'button'); /* tabelirida jääb reaks */
    el.addEventListener('keydown', e => {
      if (e.target === el && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); el.click(); }
    });
  });
  glideBars();
  if (typeof updateNotifBadge === "function") updateNotifBadge();
}

/* TOAST STACK — virnastuvad teated (beui „Animated Toast Stack" vanilla-tõlge):
   uusim ees, vanemad taanduvad sügavusse (üles + väiksemaks + hajusamaks);
   hover laotab virna lahti lugemiseks, klõps sulgeb kohe. API jäi samaks: toast(msg). */
const TOASTS = [];
function toastHost() {
  let host = document.getElementById("toasts");
  if (!host) {
    host = document.createElement("div"); host.id = "toasts"; document.body.appendChild(host);
    host.addEventListener("mouseenter", () => { host.classList.add("exp"); toastLayout(); });
    host.addEventListener("mouseleave", () => { host.classList.remove("exp"); toastLayout(); });
  }
  return host;
}
function toastLayout() {
  const exp = document.getElementById("toasts")?.classList.contains("exp");
  TOASTS.forEach((el, i) => {
    el.style.setProperty("--ty", exp ? `-${i * (el.offsetHeight + 8)}px` : `-${i * 11}px`);
    el.style.setProperty("--sc", exp ? "1" : String(Math.max(.86, 1 - i * .05)));
    el.style.setProperty("--op", exp ? "1" : i > 2 ? "0" : String(1 - i * .22));
  });
}
function toastGone(el) {
  const i = TOASTS.indexOf(el); if (i < 0) return;
  TOASTS.splice(i, 1); clearTimeout(el._t);
  el.classList.add("out");
  setTimeout(() => { el.remove(); }, 420);
  toastLayout();
}
/* v489 (UX-test V11): rakenduse oma kinnitusdialoog natiivse confirm() asemel — sama keel kui ülejäänud modaalid.
   Tagastab Promise<boolean>; Esc / taust = loobu, Enter = kinnita. Kõik kasutuskohad on pöördumatud toimingud. */
function askConfirm(msg, okLbl = "Jah, jätka") {
  return new Promise(res => {
    const el = document.createElement("div"); el.className = "cfm"; el.setAttribute("role", "alertdialog"); el.setAttribute("aria-modal", "true");
    el.innerHTML = `<div class="cfm-box"><div class="cfm-t">${escH(msg)}</div>
      <div class="cfm-b"><button class="btn btn-ghost btn-sm" data-c="0">Loobu</button><button class="btn btn-primary btn-sm" data-c="1">${escH(okLbl)}</button></div></div>`;
    const done = (v) => { document.removeEventListener("keydown", key, true); el.remove(); res(v); };
    const key = (e) => { if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); done(false); } else if (e.key === "Enter") { e.preventDefault(); done(true); } };
    el.onclick = (e) => { const b = e.target.closest("[data-c]"); if (b) done(b.dataset.c === "1"); else if (e.target === el) done(false); };
    document.addEventListener("keydown", key, true);
    document.body.appendChild(el);
    el.querySelector('[data-c="1"]').focus();
  });
}
window.askReset = async () => { if (await askConfirm("Lähtesta demo algseisu? Kõik sisestatud andmed kustuvad.", "Lähtesta")) DB.reset(); };
function toast(msg) {
  const host = toastHost();
  const el = document.createElement("div"); el.className = "toastx";
  el.innerHTML = `<span class="tic">${I.check.replace('<svg', '<svg style="width:17px;height:17px"')}</span><span class="ttx">${escH(msg)}</span>`;
  el.onclick = () => toastGone(el);
  host.appendChild(el);                          /* hilisem DOM = virna peal */
  TOASTS.unshift(el);
  el.style.setProperty("--ty", "18px"); el.style.setProperty("--sc", ".96"); el.style.setProperty("--op", "0");
  requestAnimationFrame(() => requestAnimationFrame(toastLayout));
  while (TOASTS.length > 4) toastGone(TOASTS[TOASTS.length - 1]);
  el._t = setTimeout(() => toastGone(el), 4200);
}
window.toast = toast; // inline-onclick handlerite jaoks (nt imporditud lepingu originaal)
/* teade + „Võta tagasi" (10 s): pöörduv toiming ilma kinnitusdialoogita — impordi kinnitamine, AI vestluse kustutamine */
function toastTagasi(msg, taasta, ms = 10000) {
  toast(msg);
  const el = TOASTS[0]; if (!el) return;
  const b = document.createElement("button"); b.type = "button"; b.className = "toast-undo"; b.textContent = "Võta tagasi";
  b.onclick = (e) => { e.stopPropagation(); toastGone(el); taasta(); };
  el.appendChild(b); clearTimeout(el._t); el._t = setTimeout(() => toastGone(el), ms);
}
/* salvestus võib ebaõnnestuda (localStorage täis — PDF-id ja logod on base64) → hoiata, muidu kaob muudatus
   vaikselt. Hoiatus tuleb pärast kutsuja „Salvestatud"-teadet, et jääks virna peale. quiet: kutsuja näitab ise veateadet. */
{ const dbSave = DB.save;
  DB.save = (quiet) => { const ok = dbSave(); if (!ok && !quiet) setTimeout(() => toast("Salvestamine ebaõnnestus — brauseri salvestusruum on täis. Muudatus kaob lehe uuendamisel; eemalda mõni suur fail või lähtesta demo."), 60); return ok; }; }

/* date helpers */
const MONTHS = ["jaanuar","veebruar","märts","aprill","mai","juuni","juuli","august","september","oktoober","november","detsember"];
/* v487: aasta kuvatakse, kui see ei ole jooksev aasta — „31.08" (2028) ei loe enam möödunud kuupäevana */
function fmtShort(iso){ const p = iso.split("-"); return `${p[2]}.${p[1]}${+p[0] !== DEMO_TODAY.getFullYear() ? "." + p[0] : ""}`; }
/* v487: möödunud võtmekuupäev saab märgi, et see ei paistaks eesootavana */
const kdPast = (iso) => new Date(iso) < DEMO_TODAY;
function monthName(ym){ const p = ym.split("-"); return `${MONTHS[+p[1]-1].replace(/^./,c=>c.toUpperCase())} ${p[0]}`; }

